import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { X, ChevronDown } from 'lucide-react';
import { userService } from '../../services/userService';
import { User, UserFormData, Faculty, Department } from '../../types';
import { toast } from 'react-hot-toast';
import './UserModal.css';

interface UserModalProps {
  user: User | null;
  faculties: Faculty[];
  departments: Department[];
  userRoles: string[];
  isVisible: boolean;
  onClose: () => void;
  onSave: () => void;
}

const UserModal: React.FC<UserModalProps> = ({ 
  user, 
  faculties,
  departments,
  userRoles,
  isVisible, 
  onClose, 
  onSave 
}) => {
  const [formData, setFormData] = useState<UserFormData>({
    email: '',
    userName: '',
    password: '',
    firstName: '',
    lastName: '',
    userRole: 'User',
    deptId: '',
    facultyId: '',
    phoneNumber: ''
  });
  const [isLoading, setIsLoading] = useState(false);
  const [errors, setErrors] = useState<{ [key: string]: string }>({});
  const [dropdownStates, setDropdownStates] = useState({
    role: false,
    faculty: false,
    department: false
  });

  // Filter departments by selected faculty
  const filteredDepartments = formData.facultyId 
    ? departments.filter(dept => {
        // Handle both populated faculty object and direct facultyId
        if (dept.faculty && typeof dept.faculty === 'object' && dept.faculty._id) {
          return dept.faculty._id.toString() === formData.facultyId!.toString();
        } else if (dept.facultyId) {
          return dept.facultyId.toString() === formData.facultyId!.toString();
        }
        return false;
      })
    : [];

  useEffect(() => {
    if (isVisible) {
      if (user) {
        // Edit mode - populate form with existing data
        setFormData({
          email: user.email,
          userName: user.userName,
          password: '', // Don't prefill password for edit
          firstName: user.firstName,
          lastName: user.lastName,
          userRole: user.userRole,
          deptId: user.deptId ? user.deptId.toString() : '',
          facultyId: user.facultyId ? user.facultyId.toString() : '',
          phoneNumber: user.phoneNumber || ''
        });
      } else {
        // Add mode - reset form
        setFormData({
          email: '',
          userName: '',
          password: '',
          firstName: '',
          lastName: '',
          userRole: 'User',
          deptId: '',
          facultyId: '',
          phoneNumber: ''
        });
      }
      setErrors({});
      setDropdownStates({ role: false, faculty: false, department: false });
    }
  }, [user, isVisible]);

  // Clear department when faculty changes
  useEffect(() => {
    if (formData.facultyId && formData.deptId) {
      const isDeptInFaculty = filteredDepartments.some(dept => 
        dept.id === formData.deptId || (dept._id && dept._id.toString() === formData.deptId!.toString())
      );
      if (!isDeptInFaculty) {
        setFormData(prev => ({
          ...prev,
          deptId: ''
        }));
      }
    }
  }, [formData.facultyId, formData.deptId, filteredDepartments]);

  // Password complexity validator matching Angular implementation
  const passwordComplexityValidator = (password: string): string | null => {
    if (!password) return null;

    const hasUpperCase = /[A-Z]/.test(password);
    const hasLowerCase = /[a-z]/.test(password);
    const hasNumeric = /[0-9]/.test(password);
    const hasSpecialChar = /[!@#$%^&*(),.?":{}|<>]/.test(password);

    const isValid = hasUpperCase && hasLowerCase && hasNumeric && hasSpecialChar;
    return !isValid ? 'Password must include at least one uppercase letter, one lowercase letter, one number, and one special character.' : null;
  };

  const validateForm = (): boolean => {
    const newErrors: { [key: string]: string } = {};

    if (!formData.email.trim()) {
      newErrors.email = 'Email is required';
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
      newErrors.email = 'Invalid email format';
    }

    if (!formData.userName.trim()) {
      newErrors.userName = 'Username is required';
    }

    // Password validation matching Angular exactly
    if (!user && !formData.password?.trim()) {
      newErrors.password = 'Password is required for new users';
    } else if (formData.password && formData.password.trim()) {
      // Only validate if password is provided (for both new and edit modes)
      // Minimum length check
      if (formData.password.length < 8) {
        newErrors.password = 'Password must be at least 8 characters';
      } else {
        // Complex password validation
        const complexityError = passwordComplexityValidator(formData.password);
        if (complexityError) {
          newErrors.password = complexityError;
        }
      }
    }

    if (!formData.firstName.trim()) {
      newErrors.firstName = 'First name is required';
    }

    if (!formData.lastName.trim()) {
      newErrors.lastName = 'Last name is required';
    }

    if (!formData.phoneNumber?.trim()) {
      newErrors.phoneNumber = 'Phone number is required';
    }

    if (!formData.userRole) {
      newErrors.userRole = 'Role selection is required';
    }

    // Faculty and Department are required for non-admin users
    if (formData.userRole !== 'Admin' && formData.userRole !== 'VC' && formData.userRole !== 'PVC') {
      if (!formData.facultyId) {
        newErrors.facultyId = 'Faculty selection is required';
      }
      if (!formData.deptId && formData.userRole !== 'Dean') {
        newErrors.deptId = 'Department selection is required';
      }
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleInputChange = (field: keyof UserFormData) => (
    e: React.ChangeEvent<HTMLInputElement>
  ) => {
    setFormData(prev => ({
      ...prev,
      [field]: e.target.value
    }));
    
    // Clear error when user starts typing
    if (errors[field]) {
      setErrors(prev => ({
        ...prev,
        [field]: ''
      }));
    }
  };

  const handleDropdownToggle = (dropdown: keyof typeof dropdownStates) => {
    if (isLoading) return;
    setDropdownStates(prev => ({
      ...prev,
      [dropdown]: !prev[dropdown]
    }));
  };

  const handleDropdownSelect = (field: keyof UserFormData, value: string) => {
    setFormData(prev => ({
      ...prev,
      [field]: value
    }));
    
    // Clear related department when faculty changes
    if (field === 'facultyId') {
      setFormData(prev => ({
        ...prev,
        deptId: ''
      }));
    }
    
    setDropdownStates(prev => ({
      ...prev,
      [field === 'userRole' ? 'role' : field === 'facultyId' ? 'faculty' : 'department']: false
    }));
    
    // Clear error
    if (errors[field]) {
      setErrors(prev => ({
        ...prev,
        [field]: ''
      }));
    }
  };

  const getSelectedValue = (field: keyof UserFormData): string => {
    const value = formData[field] as string;
    
    if (field === 'userRole') {
      return value || 'Select Role';
    } else if (field === 'facultyId') {
      if (!value) return 'Select Faculty';
      const faculty = faculties.find(f => f.id === value || (f._id && f._id.toString() === value.toString()));
      return faculty ? faculty.name : 'Select Faculty';
    } else if (field === 'deptId') {
      if (!value) return 'Select Department';
      // Search in all departments, not just filtered ones, to show selected value
      const department = departments.find(d => {
        return d.id === value || (d._id && d._id.toString() === value.toString());
      });
      return department ? (department.deptName || department.name) : 'Select Department';
    }
    return value;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!validateForm()) {
      return;
    }

    setIsLoading(true);
    
    try {
      if (user) {
        // Edit existing user
        await userService.updateUser(user.id, formData);
        toast.success('User updated successfully!');
      } else {
        // Create new user
        await userService.createUser(formData);
        toast.success('User created successfully!');
      }
      
      onSave(); // Refresh parent data and close modal
    } catch (error: any) {
      toast.error(error.message || 'Operation failed');
    } finally {
      setIsLoading(false);
    }
  };

  const handleClose = () => {
    if (!isLoading) {
      setDropdownStates({ role: false, faculty: false, department: false });
      onClose();
    }
  };

  const handleBackdropClick = () => {
    // Close dropdowns first, then modal
    const hasOpenDropdown = Object.values(dropdownStates).some(Boolean);
    if (hasOpenDropdown) {
      setDropdownStates({ role: false, faculty: false, department: false });
    } else {
      handleClose();
    }
  };

  // Add body scroll lock
  useEffect(() => {
    if (isVisible) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    
    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [isVisible]);

  if (!isVisible) return null;

  return createPortal(
    <div className="p-dialog-mask p-component-overlay p-component-overlay-enter" onClick={handleBackdropClick}>
        <div className="p-dialog p-component p-dialog-center user-modal" onClick={(e) => e.stopPropagation()}>
          <div className="p-dialog-content">
            {/* Modal Header */}
            <div className="p-dialog-header">
              <span className="p-dialog-title">
                {user ? 'Edit User' : 'Add User'}
              </span>
              <div className="p-dialog-header-icons">
                <button
                  className="p-dialog-header-icon p-dialog-header-close"
                  type="button"
                  onClick={handleClose}
                  disabled={isLoading}
                >
                  <X className="h-4 w-4" />
                </button>
              </div>
            </div>

            {/* Modal Body */}
            <form onSubmit={handleSubmit} className="user-form">
              <div className="p-fluid">
                {/* First Row - Username and Email */}
                <div className="form-row">
                  <div className="field col-6">
                    <label htmlFor="userName" className="required-field">
                      Username
                    </label>
                    <input
                      id="userName"
                      type="text"
                      placeholder="Enter username"
                      value={formData.userName}
                      onChange={handleInputChange('userName')}
                      className={`p-inputtext p-component ${errors.userName ? 'p-invalid' : ''}`}
                      disabled={isLoading}
                      required
                    />
                    {errors.userName && (
                      <small className="p-error">{errors.userName}</small>
                    )}
                  </div>

                  <div className="field col-6">
                    <label htmlFor="email" className="required-field">
                      Email
                    </label>
                    <input
                      id="email"
                      type="email"
                      placeholder="Enter email"
                      value={formData.email}
                      onChange={handleInputChange('email')}
                      className={`p-inputtext p-component ${errors.email ? 'p-invalid' : ''}`}
                      disabled={isLoading}
                      required
                    />
                    {errors.email && (
                      <small className="p-error">{errors.email}</small>
                    )}
                  </div>
                </div>

                {/* Password Row - Always show, with different requirements for new vs edit */}
                <div className="form-row">
                  <div className="field col-12">
                    <label htmlFor="password" className={user ? '' : 'required-field'}>
                      Password
                      {user && (
                        <span style={{ fontSize: '0.875rem', color: '#666', marginLeft: '8px' }}>
                          (Enter the New Password, Leave empty if no change is required)
                        </span>
                      )}
                    </label>
                    <input
                      id="password"
                      type="password"
                      placeholder={user ? "Enter new password (optional)" : "Enter password (minimum 8 characters)"}
                      value={formData.password || ''}
                      onChange={handleInputChange('password')}
                      className={`p-inputtext p-component ${errors.password ? 'p-invalid' : ''}`}
                      disabled={isLoading}
                      required={!user}
                      autoComplete="new-password"
                    />
                    {errors.password && (
                      <small className="p-error">{errors.password}</small>
                    )}
                  </div>
                </div>

                {/* Second Row - First Name and Last Name */}
                <div className="form-row">
                  <div className="field col-6">
                    <label htmlFor="firstName" className="required-field">
                      First Name
                    </label>
                    <input
                      id="firstName"
                      type="text"
                      placeholder="Enter first name"
                      value={formData.firstName}
                      onChange={handleInputChange('firstName')}
                      className={`p-inputtext p-component ${errors.firstName ? 'p-invalid' : ''}`}
                      disabled={isLoading}
                      required
                    />
                    {errors.firstName && (
                      <small className="p-error">{errors.firstName}</small>
                    )}
                  </div>

                  <div className="field col-6">
                    <label htmlFor="lastName" className="required-field">
                      Last Name
                    </label>
                    <input
                      id="lastName"
                      type="text"
                      placeholder="Enter last name"
                      value={formData.lastName}
                      onChange={handleInputChange('lastName')}
                      className={`p-inputtext p-component ${errors.lastName ? 'p-invalid' : ''}`}
                      disabled={isLoading}
                      required
                    />
                    {errors.lastName && (
                      <small className="p-error">{errors.lastName}</small>
                    )}
                  </div>
                </div>

                {/* Third Row - Role and Phone */}
                <div className="form-row">
                  <div className="field col-6">
                    <label className="required-field">Role</label>
                    <div className={`p-dropdown p-component ${errors.userRole ? 'p-invalid' : ''}`}>
                      <div 
                        className="p-dropdown-label-container"
                        onClick={() => handleDropdownToggle('role')}
                      >
                        <span className="p-dropdown-label">
                          {getSelectedValue('userRole')}
                        </span>
                        <div className="p-dropdown-trigger">
                          <ChevronDown className={`p-dropdown-trigger-icon ${dropdownStates.role ? 'rotated' : ''}`} />
                        </div>
                      </div>
                      
                      {dropdownStates.role && (
                        <div className="p-dropdown-panel">
                          <div className="p-dropdown-items-wrapper">
                            <ul className="p-dropdown-items">
                              {userRoles.map((role) => (
                                <li 
                                  key={role}
                                  className={`p-dropdown-item ${formData.userRole === role ? 'p-highlight' : ''}`}
                                  onClick={() => handleDropdownSelect('userRole', role)}
                                >
                                  {role}
                                </li>
                              ))}
                            </ul>
                          </div>
                        </div>
                      )}
                    </div>
                    {errors.userRole && (
                      <small className="p-error">{errors.userRole}</small>
                    )}
                  </div>

                  <div className="field col-6">
                    <label htmlFor="phoneNumber" className="required-field">
                      Phone Number
                    </label>
                    <input
                      id="phoneNumber"
                      type="text"
                      placeholder="Enter phone number"
                      value={formData.phoneNumber}
                      onChange={handleInputChange('phoneNumber')}
                      className={`p-inputtext p-component ${errors.phoneNumber ? 'p-invalid' : ''}`}
                      disabled={isLoading}
                      required
                    />
                    {errors.phoneNumber && (
                      <small className="p-error">{errors.phoneNumber}</small>
                    )}
                  </div>
                </div>

                {/* Fourth Row - Faculty and Department (conditionally shown) */}
                {formData.userRole !== 'Admin' && formData.userRole !== 'VC' && formData.userRole !== 'PVC' && (
                  <div className="form-row">
                    <div className="field col-6">
                      <label className="required-field">Faculty</label>
                      <div className={`p-dropdown p-component ${errors.facultyId ? 'p-invalid' : ''}`}>
                        <div 
                          className="p-dropdown-label-container"
                          onClick={() => handleDropdownToggle('faculty')}
                        >
                          <span className="p-dropdown-label">
                            {getSelectedValue('facultyId')}
                          </span>
                          <div className="p-dropdown-trigger">
                            <ChevronDown className={`p-dropdown-trigger-icon ${dropdownStates.faculty ? 'rotated' : ''}`} />
                          </div>
                        </div>
                        
                        {dropdownStates.faculty && (
                          <div className="p-dropdown-panel">
                            <div className="p-dropdown-items-wrapper">
                              <ul className="p-dropdown-items">
                                {faculties.length === 0 ? (
                                  <li className="p-dropdown-item p-dropdown-empty-message">
                                    No faculties available
                                  </li>
                                ) : (
                                  faculties.map((faculty) => (
                                    <li 
                                      key={faculty._id || faculty.id}
                                      className={`p-dropdown-item ${formData.facultyId === (faculty._id || faculty.id)?.toString() ? 'p-highlight' : ''}`}
                                      onClick={() => handleDropdownSelect('facultyId', (faculty._id || faculty.id)!.toString())}
                                    >
                                      {faculty.name}
                                    </li>
                                  ))
                                )}
                              </ul>
                            </div>
                          </div>
                        )}
                      </div>
                      {errors.facultyId && (
                        <small className="p-error">{errors.facultyId}</small>
                      )}
                    </div>

                    {formData.userRole !== 'Dean' && (
                      <div className="field col-6">
                        <label className="required-field">Department</label>
                        <div className={`p-dropdown p-component ${errors.deptId ? 'p-invalid' : ''} ${!formData.facultyId ? 'p-disabled' : ''}`}>
                          <div 
                            className="p-dropdown-label-container"
                            onClick={() => formData.facultyId && handleDropdownToggle('department')}
                          >
                            <span className="p-dropdown-label">
                              {!formData.facultyId ? 'Select Faculty First' : getSelectedValue('deptId')}
                            </span>
                            <div className="p-dropdown-trigger">
                              <ChevronDown className={`p-dropdown-trigger-icon ${dropdownStates.department ? 'rotated' : ''}`} />
                            </div>
                          </div>
                          
                          {dropdownStates.department && formData.facultyId && (
                            <div className="p-dropdown-panel">
                              <div className="p-dropdown-items-wrapper">
                                <ul className="p-dropdown-items">
                                  {filteredDepartments.length === 0 ? (
                                    <li className="p-dropdown-item p-dropdown-empty-message">
                                      No departments available for selected faculty
                                    </li>
                                  ) : (
                                    filteredDepartments.map((department) => (
                                      <li 
                                        key={department._id || department.id}
                                        className={`p-dropdown-item ${formData.deptId === (department._id || department.id)?.toString() ? 'p-highlight' : ''}`}
                                        onClick={() => handleDropdownSelect('deptId', (department._id || department.id)!.toString())}
                                      >
                                        {department.deptName || department.name}
                                      </li>
                                    ))
                                  )}
                                </ul>
                              </div>
                            </div>
                          )}
                        </div>
                        {errors.deptId && (
                          <small className="p-error">{errors.deptId}</small>
                        )}
                      </div>
                    )}
                  </div>
                )}
              </div>

              {/* Modal Footer */}
              <div className="p-dialog-footer">
                <button
                  type="button"
                  className="p-button p-component p-button-secondary"
                  onClick={handleClose}
                  disabled={isLoading}
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="p-button p-component p-button-primary"
                  disabled={isLoading}
                >
                  {isLoading ? (
                    <span className="p-button-loading-icon pi pi-spinner pi-spin"></span>
                  ) : null}
                  {isLoading 
                    ? 'Saving...' 
                    : (user ? 'Update User' : 'Create User')
                  }
                </button>
              </div>
            </form>
          </div>
        </div>
      </div>,
    document.body
  );
};

export default UserModal;