import React, { useState, useEffect } from 'react';
import { departmentService } from '../../../services/departmentService';
import { facultyService } from '../../../services/facultyService';
import { Department, Faculty } from '../../../types';
import { toast } from 'react-hot-toast';
import DepartmentModal from '../../../components/department-modal/DepartmentModal';
import './Departments.css';

const Departments: React.FC = () => {
  // State matching Angular component exactly
  const [pageSize] = useState<number>(100);
  const [page, setPage] = useState<number>(1);
  const [search] = useState<string>('');
  const [departments, setDepartments] = useState<Department[]>([]);
  const [faculties, setFaculties] = useState<Faculty[]>([]);
  const [first, setFirst] = useState<number>(0);
  const [rows] = useState<number>(10);
  const [totalRecords, setTotalRecords] = useState<number>(0);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isLoadingArr, setIsLoadingArr] = useState<{ [id: string]: boolean }>({});
  const [showModal, setShowModal] = useState<boolean>(false);
  const [selectedDepartment, setSelectedDepartment] = useState<Department | null>(null);

  useEffect(() => {
    loadInitialData();
  }, []);

  const loadInitialData = async () => {
    await Promise.all([
      getAllDepartments(),
      loadFaculties()
    ]);
  };

  const getAllDepartments = async () => {
    setIsLoading(true);
    try {
      const parameters = {
        page,
        pageSize,
        search,
      };
      
      const response = await departmentService.getDepartments(parameters.page, parameters.pageSize, parameters.search);
      setDepartments(response.Data || []);
      setTotalRecords(response.TotalCount || 0);
    } catch (error) {
      console.error('Error loading departments:', error);
      toast.error('Failed to load departments');
    } finally {
      setIsLoading(false);
    }
  };

  const loadFaculties = async () => {
    try {
      const response = await facultyService.getAllFaculties();
      setFaculties(response.Data || []);
    } catch (error) {
      console.error('Error loading faculties:', error);
      toast.error('Failed to load faculties');
    }
  };

  const getFacultyName = (facultyRef: string | any): string => {
    // If facultyRef is already a populated object with name
    if (typeof facultyRef === 'object' && facultyRef?.name) {
      return facultyRef.name;
    }
    
    // If facultyRef is an ID string, find in faculties array
    if (typeof facultyRef === 'string') {
      const faculty = faculties.find(f => f.id === facultyRef || f._id === facultyRef);
      return faculty ? faculty.name : '-';
    }
    
    return '-';
  };

  const editMethod = (department: Department) => {
    setSelectedDepartment(department);
    setShowModal(true);
  };

  const deleteMethod = async (id: string) => {
    // Show confirmation dialog - exact Angular SweetAlert replication
    const confirmed = window.confirm(
      "You won't be able to revert this! This will delete all data related to this Department!"
    );
    
    if (!confirmed) return;

    setIsLoadingArr(prev => ({ ...prev, [id]: true }));
    
    try {
      await departmentService.deleteDepartment(id);
      toast.success('Department Deleted Successfully');
      getAllDepartments();
    } catch (error) {
      toast.error('Failed to delete department');
    } finally {
      setIsLoadingArr(prev => ({ ...prev, [id]: false }));
    }
  };

  const pageChange = (event: { first: number; rows: number; page: number }) => {
    setFirst(event.first);
    setPage(event.page);
    getAllDepartments();
  };

  const openModal = (department: Department | null = null) => {
    setSelectedDepartment(department);
    setShowModal(true);
  };

  const closeModal = () => {
    setShowModal(false);
    setSelectedDepartment(null);
  };

  const handleSave = () => {
    // Refresh data and close modal
    getAllDepartments();
    closeModal();
  };

  return (
    <div className="departments-page">
      <h2>Department List</h2>
      
      {/* PrimeNG p-table equivalent - EXACT Angular structure */}
      <div className="p-datatable p-component">
        <div className="p-datatable-wrapper">
          <table className="p-datatable-table">
            <thead className="p-datatable-thead">
              <tr>
                <th style={{ width: '10%', textAlign: 'center' }}>S. No.</th>
                <th style={{ width: '25%', textAlign: 'center' }}>Department Name</th>
                <th style={{ width: '20%', textAlign: 'center' }}>Department Code</th>
                <th style={{ width: '25%', textAlign: 'center' }}>Faculty</th>
                <th style={{ width: '20%', textAlign: 'center' }}>Action</th>
              </tr>
            </thead>
            <tbody className="p-datatable-tbody">
              {isLoading ? (
                <tr>
                  <td colSpan={5} className="text-center p-4">
                    <div className="spinner">
                      <div className="loading-spinner"></div>
                    </div>
                  </td>
                </tr>
              ) : departments.length === 0 ? (
                <tr>
                  <td colSpan={5} className="text-center p-4">
                    No departments found
                  </td>
                </tr>
              ) : (
                departments.map((department, index) => (
                  <tr key={department.id || department._id}>
                    <td>{first + index + 1}</td>
                    <td>
                      <span className="department-name">{department.deptName || department.name}</span>
                    </td>
                    <td>
                      <span className="department-code">{department.deptCode}</span>
                    </td>
                    <td>
                      <span className="faculty-name">
                        {getFacultyName(department.facultyId || department.faculty)}
                      </span>
                    </td>
                    <td>
                      <div className="action-buttons">
                        <button
                          className="action-btn edit-btn"
                          onClick={() => editMethod(department)}
                          title="Edit Department"
                        >
                          <img
                            src="/assets/icons/ic--round-edit.svg"
                            alt="edit-icon"
                          />
                        </button>
                        <button
                          className="action-btn delete-btn"
                          onClick={() => deleteMethod(department.id)}
                          title="Delete Department"
                          disabled={isLoadingArr[department.id]}
                        >
                          {isLoadingArr[department.id] ? (
                            <div className="spinner">
                              <div className="loading-spinner small"></div>
                            </div>
                          ) : (
                            <img
                              src="/assets/icons/ep--delete-filled.svg"
                              alt="delete-icon"
                            />
                          )}
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* PrimeNG p-paginator equivalent - EXACT Angular structure */}
      <div className="p-paginator p-component p-paginator-bottom">
        <span className="p-paginator-current">
          Showing {first + 1} to {Math.min(first + rows, totalRecords)} of {totalRecords}
        </span>
        {/* Future: Add pagination controls when needed */}
      </div>

      {/* Add Button - PrimeNG floating action button - EXACT Angular styling */}
      <button
        className="p-button p-button-rounded p-button-icon-only p-button-fab"
        onClick={() => openModal()}
        title="Add Department"
      >
        <span className="pi pi-plus"></span>
      </button>

      {/* Department Modal for Create/Edit */}
      <DepartmentModal
        department={selectedDepartment}
        faculties={faculties}
        isVisible={showModal}
        onClose={closeModal}
        onSave={handleSave}
      />
    </div>
  );
};

export default Departments;