import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { X, ChevronDown } from 'lucide-react';
import { departmentService } from '../../services/departmentService';
import { Department, DepartmentFormData, Faculty } from '../../types';
import { toast } from 'react-hot-toast';
import './DepartmentModal.css';

interface DepartmentModalProps {
  department: Department | null;
  faculties: Faculty[];
  isVisible: boolean;
  onClose: () => void;
  onSave: () => void;
}

const DepartmentModal: React.FC<DepartmentModalProps> = ({ 
  department, 
  faculties,
  isVisible, 
  onClose, 
  onSave 
}) => {
  const [formData, setFormData] = useState<DepartmentFormData>({
    deptName: '',
    deptCode: '',
    faculty: ''
  });
  const [isLoading, setIsLoading] = useState(false);
  const [errors, setErrors] = useState<{ [key: string]: string }>({});
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);

  useEffect(() => {
    if (isVisible) {
      if (department) {
        // Edit mode - populate form with existing data
        setFormData({
          deptName: department.name,
          deptCode: (department as any).deptCode || '',
          faculty: department.facultyId || ''
        });
      } else {
        // Add mode - reset form
        setFormData({
          deptName: '',
          deptCode: '',
          faculty: ''
        });
      }
      setErrors({});
      setIsDropdownOpen(false);
    }
  }, [department, isVisible]);

  const validateForm = (): boolean => {
    const newErrors: { [key: string]: string } = {};

    if (!formData.deptName.trim()) {
      newErrors.deptName = 'Department name is required';
    }

    if (!formData.deptCode.trim()) {
      newErrors.deptCode = 'Department code is required';
    }

    if (!formData.faculty) {
      newErrors.faculty = 'Faculty selection is required';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleInputChange = (field: keyof DepartmentFormData) => (
    e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>
  ) => {
    setFormData(prev => ({
      ...prev,
      [field]: e.target.value
    }));
    
    // Clear error when user starts typing
    if (errors[field]) {
      setErrors(prev => ({
        ...prev,
        [field]: ''
      }));
    }
  };

  const handleFacultySelect = (facultyId: string) => {
    setFormData(prev => ({
      ...prev,
      faculty: facultyId
    }));
    setIsDropdownOpen(false);
    
    // Clear faculty error
    if (errors.faculty) {
      setErrors(prev => ({
        ...prev,
        faculty: ''
      }));
    }
  };

  const getSelectedFacultyName = (): string => {
    if (!formData.faculty) return 'Select Faculty';
    const faculty = faculties.find(f => f.id === formData.faculty || f._id === formData.faculty);
    return faculty ? faculty.name : 'Select Faculty';
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!validateForm()) {
      return;
    }

    setIsLoading(true);
    
    try {
      if (department) {
        // Edit existing department
        await departmentService.updateDepartment(department.id, formData);
        toast.success('Department updated successfully!');
      } else {
        // Create new department
        await departmentService.createDepartment(formData);
        toast.success('Department created successfully!');
      }
      
      onSave(); // Refresh parent data and close modal
    } catch (error: any) {
      toast.error(error.message || 'Operation failed');
    } finally {
      setIsLoading(false);
    }
  };

  const handleClose = () => {
    if (!isLoading) {
      setIsDropdownOpen(false);
      onClose();
    }
  };

  const handleBackdropClick = (e: React.MouseEvent) => {
    if (isDropdownOpen) {
      setIsDropdownOpen(false);
    } else {
      handleClose();
    }
  };

  // Add body scroll lock
  useEffect(() => {
    if (isVisible) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    
    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [isVisible]);

  if (!isVisible) return null;

  return createPortal(
    <div className="p-dialog-mask p-component-overlay p-component-overlay-enter" onClick={handleBackdropClick}>
      <div className="p-dialog p-component p-dialog-center" onClick={(e) => e.stopPropagation()}>
        <div className="p-dialog-content">
            {/* Modal Header */}
            <div className="p-dialog-header">
              <span className="p-dialog-title">
                {department ? 'Edit Department' : 'Add Department'}
              </span>
              <div className="p-dialog-header-icons">
                <button
                  className="p-dialog-header-icon p-dialog-header-close"
                  type="button"
                  onClick={handleClose}
                  disabled={isLoading}
                >
                  <X className="h-4 w-4" />
                </button>
              </div>
            </div>

            {/* Modal Body */}
            <form onSubmit={handleSubmit} className="department-form">
              <div className="p-fluid">
                {/* Department Name Field */}
                <div className="field col-12">
                  <label htmlFor="departmentName" className="required-field">
                    Department Name
                  </label>
                  <input
                    id="departmentName"
                    type="text"
                    placeholder="Enter department name"
                    value={formData.deptName}
                    onChange={handleInputChange('deptName')}
                    className={`p-inputtext p-component ${errors.deptName ? 'p-invalid' : ''}`}
                    disabled={isLoading}
                    required
                  />
                  {errors.deptName && (
                    <small className="p-error">{errors.deptName}</small>
                  )}
                </div>

                {/* Department Code Field */}
                <div className="field col-12">
                  <label htmlFor="deptCode" className="required-field">
                    Department Code
                  </label>
                  <input
                    id="deptCode"
                    type="text"
                    placeholder="Enter department code (e.g., CS, EE)"
                    value={formData.deptCode}
                    onChange={handleInputChange('deptCode')}
                    className={`p-inputtext p-component ${errors.deptCode ? 'p-invalid' : ''}`}
                    disabled={isLoading}
                    required
                    style={{ textTransform: 'uppercase' }}
                  />
                  {errors.deptCode && (
                    <small className="p-error">{errors.deptCode}</small>
                  )}
                </div>


                {/* Faculty Selection Dropdown - PrimeNG p-dropdown equivalent */}
                <div className="field col-12">
                  <label htmlFor="facultySelect" className="required-field">
                    Faculty
                  </label>
                  <div className={`p-dropdown p-component ${errors.faculty ? 'p-invalid' : ''}`}>
                    <div 
                      className="p-dropdown-label-container"
                      onClick={() => !isLoading && setIsDropdownOpen(!isDropdownOpen)}
                    >
                      <span className="p-dropdown-label">
                        {getSelectedFacultyName()}
                      </span>
                      <div className="p-dropdown-trigger">
                        <ChevronDown className={`p-dropdown-trigger-icon ${isDropdownOpen ? 'rotated' : ''}`} />
                      </div>
                    </div>
                    
                    {isDropdownOpen && (
                      <div className="p-dropdown-panel">
                        <div className="p-dropdown-items-wrapper">
                          <ul className="p-dropdown-items">
                            {faculties.length === 0 ? (
                              <li className="p-dropdown-item p-dropdown-empty-message">
                                No faculties available
                              </li>
                            ) : (
                              faculties.map((faculty) => (
                                <li 
                                  key={faculty.id || faculty._id}
                                  className={`p-dropdown-item ${formData.faculty === faculty.id ? 'p-highlight' : ''}`}
                                  onClick={() => handleFacultySelect(faculty.id)}
                                >
                                  {faculty.name}
                                </li>
                              ))
                            )}
                          </ul>
                        </div>
                      </div>
                    )}
                  </div>
                  {errors.faculty && (
                    <small className="p-error">{errors.faculty}</small>
                  )}
                </div>
              </div>

              {/* Modal Footer */}
              <div className="p-dialog-footer">
                <button
                  type="button"
                  className="p-button p-component p-button-secondary"
                  onClick={handleClose}
                  disabled={isLoading}
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="p-button p-component p-button-primary"
                  disabled={isLoading}
                >
                  {isLoading ? (
                    <span className="p-button-loading-icon pi pi-spinner pi-spin"></span>
                  ) : null}
                  {isLoading 
                    ? 'Saving...' 
                    : (department ? 'Update Department' : 'Create Department')
                  }
                </button>
              </div>
            </form>
          </div>
        </div>
      </div>,
    document.body
  );
};

export default DepartmentModal;