import React, { useState, useEffect } from 'react';
import { categoryService } from '../../../services/categoryService';
import { Category } from '../../../types';
import { toast } from 'react-hot-toast';
import CategoryModal from '../../../components/category-modal/CategoryModal';
import './Categories.css';

const Categories: React.FC = () => {
  // State matching Angular component exactly
  const [pageSize] = useState<number>(100);
  const [page, setPage] = useState<number>(1);
  const [search] = useState<string>('');
  const [categories, setCategories] = useState<Category[]>([]);
  const [first, setFirst] = useState<number>(0);
  const [rows] = useState<number>(10);
  const [totalRecords, setTotalRecords] = useState<number>(0);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isLoadingArr, setIsLoadingArr] = useState<{ [id: string]: boolean }>({});
  const [showModal, setShowModal] = useState<boolean>(false);
  const [selectedCategory, setSelectedCategory] = useState<Category | null>(null);

  useEffect(() => {
    getAllCategories();
  }, []);

  const getAllCategories = async () => {
    setIsLoading(true);
    try {
      const parameters = {
        page,
        pageSize,
        search,
      };

      const response = await categoryService.getCategories(parameters.page, parameters.pageSize, parameters.search);
      setCategories(response.Data || []);
      setTotalRecords(response.TotalCount || 0);
    } catch (error) {
      console.error('Error loading categories:', error);
      toast.error('Failed to load pillars');
    } finally {
      setIsLoading(false);
    }
  };

  const editMethod = (category: Category) => {
    setSelectedCategory(category);
    setShowModal(true);
  };

  const deleteMethod = async (id: string) => {
    // Show confirmation dialog - exact Angular SweetAlert replication
    const confirmed = window.confirm(
      "You won't be able to revert this! This will delete all data related to this Pillar!"
    );

    if (!confirmed) return;

    setIsLoadingArr(prev => ({ ...prev, [id]: true }));

    try {
      await categoryService.deleteCategory(id);
      toast.success('Pillar Deleted Successfully');
      getAllCategories();
    } catch (error) {
      toast.error('Failed to delete pillar');
    } finally {
      setIsLoadingArr(prev => ({ ...prev, [id]: false }));
    }
  };

  const pageChange = (event: { first: number; rows: number; page: number }) => {
    setFirst(event.first);
    setPage(event.page);
    getAllCategories();
  };

  const openModal = (category: Category | null = null) => {
    setSelectedCategory(category);
    setShowModal(true);
  };

  const closeModal = () => {
    setShowModal(false);
    setSelectedCategory(null);
  };

  const handleSave = () => {
    // Refresh data and close modal
    getAllCategories();
    closeModal();
  };

  return (
    <div className="categories-page">
      <h2>Pillars</h2>

      {/* PrimeNG p-table equivalent - EXACT Angular structure */}
      <div className="p-datatable p-component">
        <div className="p-datatable-wrapper">
          <table className="p-datatable-table">
            <thead className="p-datatable-thead">
              <tr>
                <th style={{ width: '10%', textAlign: 'center' }}>S. No.</th>
                <th style={{ width: '30%', textAlign: 'center' }}>Pillar Name</th>
                <th style={{ width: '40%', textAlign: 'center' }}>Description</th>
                <th style={{ width: '10%', textAlign: 'center' }}>Sort Order</th>
                <th style={{ width: '10%', textAlign: 'center' }}>Actions</th>
              </tr>
            </thead>
            <tbody className="p-datatable-tbody">
              {isLoading ? (
                <tr>
                  <td colSpan={5} className="text-center p-4">
                    <div className="spinner">
                      <div className="loading-spinner"></div>
                    </div>
                  </td>
                </tr>
              ) : categories.length === 0 ? (
                <tr>
                  <td colSpan={5} className="text-center p-4">
                    No pillars found
                  </td>
                </tr>
              ) : (
                categories.map((category, index) => (
                  <tr key={category.id || category._id}>
                    <td>{first + index + 1}</td>
                    <td>
                      <span className="category-name">{category.name}</span>
                    </td>
                    <td>
                      <span className="category-description">
                        {category.description || '-'}
                      </span>
                    </td>
                    <td>
                      <span className="sort-order">{category.sortOrder}</span>
                    </td>
                    <td>
                      <div className="action-buttons">
                        <button
                          className="action-btn edit-btn"
                          onClick={() => editMethod(category)}
                          title="Edit Category"
                        >
                          <img
                            src="/assets/icons/ic--round-edit.svg"
                            alt="edit-icon"
                          />
                        </button>
                        <button
                          className="action-btn delete-btn"
                          onClick={() => deleteMethod(category.id)}
                          title="Delete Category"
                          disabled={isLoadingArr[category.id]}
                        >
                          {isLoadingArr[category.id] ? (
                            <div className="spinner">
                              <div className="loading-spinner small"></div>
                            </div>
                          ) : (
                            <img
                              src="/assets/icons/ep--delete-filled.svg"
                              alt="delete-icon"
                            />
                          )}
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* PrimeNG p-paginator equivalent - EXACT Angular structure */}
      <div className="p-paginator p-component p-paginator-bottom">
        <span className="p-paginator-current">
          Showing {first + 1} to {Math.min(first + rows, totalRecords)} of {totalRecords}
        </span>
        {/* Future: Add pagination controls when needed */}
      </div>

      {/* Add Button - PrimeNG floating action button - EXACT Angular styling */}
      <button
        className="p-button p-button-rounded p-button-icon-only p-button-fab"
        onClick={() => openModal()}
        title="Add Pillar"
      >
        <span className="pi pi-plus"></span>
      </button>

      {/* Category Modal for Create/Edit */}
      <CategoryModal
        category={selectedCategory}
        isVisible={showModal}
        onClose={closeModal}
        onSave={handleSave}
      />
    </div>
  );
};

export default Categories;
