import React, { useState, useEffect } from 'react';
import { parameterService } from '../../../services/parameterService';
import { categoryService } from '../../../services/categoryService';
import { Parameter, Category, UserGroup } from '../../../types';
import { toast } from 'react-hot-toast';
import ParameterModal from '../../../components/parameter-modal/ParameterModal';
import './Parameters.css';

const Parameters: React.FC = () => {
  // State matching Angular component exactly
  const [pageSize] = useState<number>(100);
  const [page, setPage] = useState<number>(1);
  const [search] = useState<string>('');
  const [parameters, setParameters] = useState<Parameter[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [cycles, setCycles] = useState<Array<{id: string, name: string}>>([]);
  const [parameterTypes, setParameterTypes] = useState<string[]>([]);
  const [userGroups, setUserGroups] = useState<UserGroup[]>([]); // ➕ NEW: User groups for access control
  const [first, setFirst] = useState<number>(0);
  const [rows] = useState<number>(10);
  const [totalRecords, setTotalRecords] = useState<number>(0);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isLoadingArr, setIsLoadingArr] = useState<{ [id: string]: boolean }>({});
  const [showModal, setShowModal] = useState<boolean>(false);
  const [selectedParameter, setSelectedParameter] = useState<Parameter | null>(null);

  useEffect(() => {
    loadInitialData();
  }, []);

  const loadInitialData = async () => {
    await Promise.all([
      getAllParameters(),
      loadCategories(),
      loadCycles(),
      loadParameterTypes(),
      loadUserGroups() // ➕ NEW: Load user groups
    ]);
  };

  const getAllParameters = async () => {
    setIsLoading(true);
    try {
      const parameters = {
        page,
        pageSize,
        search,
      };
      
      const response = await parameterService.getParameters(parameters.page, parameters.pageSize, parameters.search);
      setParameters(response.Data || []);
      setTotalRecords(response.TotalCount || 0);
    } catch (error) {
      console.error('Error loading parameters:', error);
      toast.error('Failed to load parameters');
    } finally {
      setIsLoading(false);
    }
  };

  const loadCategories = async () => {
    try {
      const response = await categoryService.getCategories(1, 200); // Get all categories
      setCategories(response.Data || []);
    } catch (error) {
      console.error('Error loading categories:', error);
      toast.error('Failed to load categories');
    }
  };

  const loadCycles = async () => {
    try {
      // Use the proper cycles endpoint from parameter controller
      const response = await parameterService.getCycles();
      const cycles = response.Data || [];
      
      // If no cycles from database, seed default cycles and retry
      if (cycles.length === 0) {
        try {
          // Try to seed default cycles
          await parameterService.seedDefaultCycles();
          const retryResponse = await parameterService.getCycles();
          const retryCycles = retryResponse.Data || [];
          setCycles(retryCycles.map((cycle: any) => ({ id: cycle.id, name: cycle.name })));
        } catch (seedError) {
          console.warn('Could not seed cycles, using fallback');
          // Fallback to hardcoded cycle names (including 2029 as per original system)
          setCycles([
            { id: 'fallback-1', name: '2023-2024' },
            { id: 'fallback-2', name: '2024-2025' },
            { id: 'fallback-3', name: '2025-2026' },
            { id: 'fallback-4', name: '2026-2027' },
            { id: 'fallback-5', name: '2027-2028' },
            { id: 'fallback-6', name: '2028-2029' }
          ]);
        }
      } else {
        setCycles(cycles.map((cycle: any) => ({ id: cycle.id, name: cycle.name })));
      }
    } catch (error) {
      console.error('Error loading cycles:', error);
      // Set fallback cycles if API fails (including 2029 as per original system)
      setCycles([
        { id: 'fallback-1', name: '2023-2024' },
        { id: 'fallback-2', name: '2024-2025' },
        { id: 'fallback-3', name: '2025-2026' },
        { id: 'fallback-4', name: '2026-2027' },
        { id: 'fallback-5', name: '2027-2028' },
        { id: 'fallback-6', name: '2028-2029' }
      ]);
    }
  };

  const loadParameterTypes = async () => {
    try {
      const response = await parameterService.getDistinctParameterTypes();
      const types = response.Data || [];
      
      // Always provide standard parameter types
      if (types.length === 0) {
        setParameterTypes(['Numeric', 'Text', 'Percentage', 'Boolean']);
      } else {
        setParameterTypes(types);
      }
    } catch (error) {
      console.error('Error loading parameter types:', error);
      // Set default parameter types if API fails
      setParameterTypes(['Numeric', 'Text', 'Percentage', 'Boolean']);
    }
  };

  // ➕ NEW: Load user groups for group access control
  const loadUserGroups = async () => {
    try {
      const response = await parameterService.getUserGroups();
      const groups = response.Data || [];
      setUserGroups(groups);
    } catch (error) {
      console.error('Error loading user groups:', error);
      // Set fallback groups if API fails
      setUserGroups([
        { value: 'Academic Departments', label: 'Academic Departments (All Engineering/Science)' },
        { value: 'ORIC', label: 'ORIC - Research & Innovation' },
        { value: 'QEC', label: 'QEC - Quality Enhancement' },
        { value: 'CSA', label: 'CSA - Student Affairs' }
      ]);
    }
  };

  const getCategoryName = (categoryName: string): string => {
    // Parameters store category as string name, not ID
    return categoryName || '-';
  };

  const getParameterTypeColor = (type: string): string => {
    switch (type) {
      case 'Numeric': return '#3498db';
      case 'Text': return '#27ae60';
      case 'Percentage': return '#e67e22';
      case 'Boolean': return '#9b59b6';
      default: return '#6c757d';
    }
  };

  const editMethod = (parameter: Parameter) => {
    setSelectedParameter(parameter);
    setShowModal(true);
  };

  const deleteMethod = async (id: string) => {
    // Show confirmation dialog - exact Angular SweetAlert replication
    const confirmed = window.confirm(
      "You won't be able to revert this! This will delete all data related to this Parameter!"
    );
    
    if (!confirmed) return;

    setIsLoadingArr(prev => ({ ...prev, [id]: true }));
    
    try {
      await parameterService.deleteParameter(id);
      toast.success('Parameter Deleted Successfully');
      getAllParameters();
    } catch (error) {
      toast.error('Failed to delete parameter');
    } finally {
      setIsLoadingArr(prev => ({ ...prev, [id]: false }));
    }
  };

  const pageChange = (event: { first: number; rows: number; page: number }) => {
    setFirst(event.first);
    setPage(event.page);
    getAllParameters();
  };

  const openModal = (parameter: Parameter | null = null) => {
    setSelectedParameter(parameter);
    setShowModal(true);
  };

  const closeModal = () => {
    setShowModal(false);
    setSelectedParameter(null);
  };

  const handleSave = () => {
    // Refresh data and close modal
    getAllParameters();
    closeModal();
  };

  return (
    <div className="parameters-page">
      <h2>Parameters Management</h2>
      
      {/* PrimeNG p-table equivalent - EXACT Angular structure */}
      <div className="p-datatable p-component">
        <div className="p-datatable-wrapper">
          <table className="p-datatable-table">
            <thead className="p-datatable-thead">
              <tr>
                <th style={{ width: '10%', textAlign: 'center' }}>S. No.</th>
                <th style={{ width: '30%', textAlign: 'center' }}>Parameter Name</th>
                <th style={{ width: '10%', textAlign: 'center' }}>Parameter Type</th>
                <th style={{ width: '20%', textAlign: 'center' }}>Description</th>
                <th style={{ width: '20%', textAlign: 'center' }}>Pillar</th>
                <th style={{ width: '10%', textAlign: 'center' }}>Sort Order</th>
                <th style={{ width: '20%', textAlign: 'center' }}>Action</th>
              </tr>
            </thead>
            <tbody className="p-datatable-tbody">
              {isLoading ? (
                <tr>
                  <td colSpan={7} className="text-center p-4">
                    <div className="spinner">
                      <div className="loading-spinner"></div>
                    </div>
                  </td>
                </tr>
              ) : parameters.length === 0 ? (
                <tr>
                  <td colSpan={7} className="text-center p-4">
                    No parameters found
                  </td>
                </tr>
              ) : (
                parameters.map((parameter, index) => (
                  <tr key={parameter.id || parameter._id}>
                    <td>{first + index + 1}</td>
                    <td>
                      <span className="parameter-name">{(parameter as any).parameterName || parameter.name}</span>
                    </td>
                    <td>
                      <span 
                        className="parameter-type-badge"
                        style={{ backgroundColor: getParameterTypeColor(parameter.parameterType) }}
                      >
                        {(parameter as any).paramterType || parameter.parameterType}
                      </span>
                    </td>
                    <td>
                      <span className="parameter-description">
                        {parameter.description || '-'}
                      </span>
                    </td>
                    <td>
                      <span className="category-name">
                        {getCategoryName(parameter.category)}
                      </span>
                    </td>
                    <td>
                      <span className="sort-order">
                        {(parameter as any).sortOrder || 0}
                      </span>
                    </td>
                    <td>
                      <div className="action-buttons">
                        <button
                          className="action-btn edit-btn"
                          onClick={() => editMethod(parameter)}
                          title="Edit Parameter"
                        >
                          <img
                            src="/assets/icons/ic--round-edit.svg"
                            alt="edit-icon"
                          />
                        </button>
                        <button
                          className="action-btn delete-btn"
                          onClick={() => {
                            const paramId = parameter.id || parameter._id;
                            if (paramId) deleteMethod(paramId);
                          }}
                          title="Delete Parameter"
                          disabled={(() => {
                            const paramId = parameter.id || parameter._id;
                            return paramId ? isLoadingArr[paramId] || false : false;
                          })()}
                        >
                          {(() => {
                            const paramId = parameter.id || parameter._id;
                            return paramId ? isLoadingArr[paramId] : false;
                          })() ? (
                            <div className="spinner">
                              <div className="loading-spinner small"></div>
                            </div>
                          ) : (
                            <img
                              src="/assets/icons/ep--delete-filled.svg"
                              alt="delete-icon"
                            />
                          )}
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* PrimeNG p-paginator equivalent - EXACT Angular structure */}
      <div className="p-paginator p-component p-paginator-bottom">
        <span className="p-paginator-current">
          Showing {first + 1} to {Math.min(first + rows, totalRecords)} of {totalRecords}
        </span>
      </div>

      {/* Add Button - PrimeNG floating action button - EXACT Angular styling */}
      <button
        className="p-button p-button-rounded p-button-icon-only p-button-fab"
        onClick={() => openModal()}
        title="Add Parameter"
      >
        <span className="pi pi-plus"></span>
      </button>

      {/* Parameter Modal for Create/Edit */}
      <ParameterModal
        parameter={selectedParameter}
        categories={categories}
        cycles={cycles}
        parameterTypes={parameterTypes}
        userGroups={userGroups}
        isVisible={showModal}
        onClose={closeModal}
        onSave={handleSave}
      />
    </div>
  );
};

export default Parameters;