import axios from 'axios';

const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/';

interface LoginRequest {
  Username: string;
  Password: string;
}

interface LoginResponse {
  token: string;
  role: string[];
  expiration: string;
}

interface RegisterRequest {
  Username: string;
  Email: string;
  PhoneNumber: string;
  Password: string;
  UserRole: string;
  FirstName: string;
  LastName: string;
  DeptId: number;
  FacultyId: number;
}

interface UpdatePasswordRequest {
  Username: string;
  OldPassword: string;
  NewPassword: string;
}

class AuthService {
  public axiosInstance; // Make it public so other services can use it

  constructor() {
    this.axiosInstance = axios.create({
      baseURL: API_BASE_URL,
      headers: {
        'Content-Type': 'application/json',
      },
    });

    // Request interceptor to add auth token
    this.axiosInstance.interceptors.request.use(
      (config) => {
        const token = localStorage.getItem('token');
        if (token) {
          config.headers.Authorization = `Bearer ${token}`;
        }
        return config;
      },
      (error) => {
        return Promise.reject(error);
      }
    );

    // Response interceptor for error handling
    this.axiosInstance.interceptors.response.use(
      (response) => response,
      (error) => {
        if (error.response?.status === 401) {
          // Token expired or invalid
          localStorage.removeItem('token');
          localStorage.removeItem('userRole');
          localStorage.removeItem('tokenExpiration');
          window.location.href = '/';
        }
        return Promise.reject(error);
      }
    );
  }

  async login(credentials: LoginRequest): Promise<LoginResponse> {
    try {
      const response = await this.axiosInstance.post('/api/auth/login', credentials);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      } else if (error.response?.data?.message) {
        throw new Error(error.response.data.message);
      }
      throw new Error('Login failed. Please try again.');
    }
  }

  async register(userData: RegisterRequest): Promise<any> {
    try {
      const response = await this.axiosInstance.post('/api/auth/register', userData);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Registration failed. Please try again.');
    }
  }

  async registerAdmin(userData: { Username: string; Email: string; Password: string }): Promise<any> {
    try {
      const response = await this.axiosInstance.post('/api/auth/register-admin', userData);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Admin registration failed. Please try again.');
    }
  }

  async updatePassword(data: UpdatePasswordRequest): Promise<any> {
    try {
      const response = await this.axiosInstance.post('/api/auth/update-password', data);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Password update failed. Please try again.');
    }
  }

  async updateUser(username: string, userData: any): Promise<any> {
    try {
      const response = await this.axiosInstance.post(`/api/auth/update-user/${username}`, userData);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('User update failed. Please try again.');
    }
  }

  async getCurrentUser(): Promise<any> {
    try {
      const response = await this.axiosInstance.get('/api/users/get-current-user');
      return response.data.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Failed to get current user. Please try again.');
    }
  }
}

export const authService = new AuthService();