import React, { useState, useMemo } from 'react';
import { ChevronUp, ChevronDown, Search, Filter, X } from 'lucide-react';
import './DataTable.css';

export interface Column<T> {
  key: keyof T;
  label: string;
  width?: string;
  sortable?: boolean;
  filterable?: boolean;
  renderCell?: (item: T, value: any) => React.ReactNode;
  filterType?: 'text' | 'select' | 'number' | 'date';
  filterOptions?: Array<{ label: string; value: string }>;
}

export interface DataTableProps<T> {
  data: T[];
  columns: Column<T>[];
  loading?: boolean;
  pagination?: {
    current: number;
    pageSize: number;
    total: number;
    onChange: (page: number, pageSize: number) => void;
  };
  searchable?: boolean;
  exportable?: boolean;
  onExport?: () => void;
  className?: string;
  emptyMessage?: string;
}

export interface SortConfig {
  key: string;
  direction: 'asc' | 'desc';
}

export interface FilterConfig {
  [key: string]: string;
}

function DataTable<T extends Record<string, any>>({
  data,
  columns,
  loading = false,
  pagination,
  searchable = false,
  exportable = false,
  onExport,
  className = '',
  emptyMessage = 'No data available'
}: DataTableProps<T>) {
  const [sortConfig, setSortConfig] = useState<SortConfig | null>(null);
  const [filters, setFilters] = useState<FilterConfig>({});
  const [globalSearch, setGlobalSearch] = useState('');
  const [showFilters, setShowFilters] = useState(false);

  // Sorting function
  const handleSort = (key: string) => {
    let direction: 'asc' | 'desc' = 'asc';
    
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    
    setSortConfig({ key, direction });
  };

  // Filter functions
  const handleFilterChange = (key: string, value: string) => {
    setFilters(prev => ({
      ...prev,
      [key]: value
    }));
  };

  const clearFilters = () => {
    setFilters({});
    setGlobalSearch('');
  };

  const clearFilter = (key: string) => {
    setFilters(prev => {
      const newFilters = { ...prev };
      delete newFilters[key];
      return newFilters;
    });
  };

  // Process data with search, filter, and sort
  const processedData = useMemo(() => {
    let filtered = [...data];

    // Global search
    if (globalSearch) {
      const searchLower = globalSearch.toLowerCase();
      filtered = filtered.filter(item =>
        columns.some(column => {
          const value = item[column.key];
          return value?.toString().toLowerCase().includes(searchLower);
        })
      );
    }

    // Column filters
    Object.entries(filters).forEach(([key, value]) => {
      if (value) {
        filtered = filtered.filter(item => {
          const itemValue = item[key];
          if (itemValue == null) return false;
          
          const column = columns.find(col => col.key === key);
          if (column?.filterType === 'select') {
            return itemValue.toString() === value;
          }
          
          return itemValue.toString().toLowerCase().includes(value.toLowerCase());
        });
      }
    });

    // Sorting
    if (sortConfig) {
      filtered.sort((a, b) => {
        const aValue = a[sortConfig.key];
        const bValue = b[sortConfig.key];
        
        if (aValue == null) return 1;
        if (bValue == null) return -1;
        
        let comparison = 0;
        if (typeof aValue === 'number' && typeof bValue === 'number') {
          comparison = aValue - bValue;
        } else {
          comparison = aValue.toString().localeCompare(bValue.toString());
        }
        
        return sortConfig.direction === 'desc' ? -comparison : comparison;
      });
    }

    return filtered;
  }, [data, columns, globalSearch, filters, sortConfig]);

  const activeFiltersCount = Object.values(filters).filter(Boolean).length + (globalSearch ? 1 : 0);

  return (
    <div className={`enhanced-datatable ${className}`}>
      {/* Table Controls */}
      {(searchable || exportable || activeFiltersCount > 0) && (
        <div className="table-controls">
          <div className="controls-left">
            {searchable && (
              <div className="search-container">
                <Search className="search-icon" />
                <input
                  type="text"
                  placeholder="Search across all columns..."
                  value={globalSearch}
                  onChange={(e) => setGlobalSearch(e.target.value)}
                  className="global-search"
                />
                {globalSearch && (
                  <button
                    className="clear-search"
                    onClick={() => setGlobalSearch('')}
                  >
                    <X className="h-4 w-4" />
                  </button>
                )}
              </div>
            )}
            
            <button
              className={`filter-toggle ${showFilters ? 'active' : ''}`}
              onClick={() => setShowFilters(!showFilters)}
            >
              <Filter className="h-4 w-4" />
              Filters
              {activeFiltersCount > 0 && (
                <span className="filter-count">{activeFiltersCount}</span>
              )}
            </button>

            {activeFiltersCount > 0 && (
              <button className="clear-all-filters" onClick={clearFilters}>
                Clear All
              </button>
            )}
          </div>

          <div className="controls-right">
            {exportable && onExport && (
              <button className="export-btn" onClick={onExport}>
                Export
              </button>
            )}
          </div>
        </div>
      )}

      {/* Active Filters Display */}
      {activeFiltersCount > 0 && (
        <div className="active-filters">
          {globalSearch && (
            <div className="filter-tag">
              <span>Search: "{globalSearch}"</span>
              <button onClick={() => setGlobalSearch('')}>
                <X className="h-3 w-3" />
              </button>
            </div>
          )}
          
          {Object.entries(filters).map(([key, value]) => {
            if (!value) return null;
            const column = columns.find(col => col.key === key);
            return (
              <div key={key} className="filter-tag">
                <span>{column?.label}: "{value}"</span>
                <button onClick={() => clearFilter(key)}>
                  <X className="h-3 w-3" />
                </button>
              </div>
            );
          })}
        </div>
      )}

      {/* Column Filters */}
      {showFilters && (
        <div className="column-filters">
          {columns
            .filter(column => column.filterable)
            .map(column => (
              <div key={column.key as string} className="filter-field">
                <label>{column.label}</label>
                
                {column.filterType === 'select' && column.filterOptions ? (
                  <select
                    value={filters[column.key as string] || ''}
                    onChange={(e) => handleFilterChange(column.key as string, e.target.value)}
                  >
                    <option value="">All</option>
                    {column.filterOptions.map(option => (
                      <option key={option.value} value={option.value}>
                        {option.label}
                      </option>
                    ))}
                  </select>
                ) : (
                  <input
                    type={column.filterType || 'text'}
                    placeholder={`Filter by ${column.label.toLowerCase()}`}
                    value={filters[column.key as string] || ''}
                    onChange={(e) => handleFilterChange(column.key as string, e.target.value)}
                  />
                )}
              </div>
            ))}
        </div>
      )}

      {/* Data Table */}
      <div className="datatable-container">
        <div className="datatable-wrapper">
          <table className="datatable">
            <thead>
              <tr>
                {columns.map(column => (
                  <th
                    key={column.key as string}
                    style={{ width: column.width }}
                    className={column.sortable ? 'sortable' : ''}
                    onClick={() => column.sortable && handleSort(column.key as string)}
                  >
                    <div className="th-content">
                      <span>{column.label}</span>
                      {column.sortable && (
                        <div className="sort-indicators">
                          <ChevronUp 
                            className={`sort-icon ${
                              sortConfig?.key === column.key && sortConfig.direction === 'asc' 
                                ? 'active' : ''
                            }`} 
                          />
                          <ChevronDown 
                            className={`sort-icon ${
                              sortConfig?.key === column.key && sortConfig.direction === 'desc' 
                                ? 'active' : ''
                            }`} 
                          />
                        </div>
                      )}
                    </div>
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {loading ? (
                <tr>
                  <td colSpan={columns.length} className="loading-cell">
                    <div className="loading-spinner-container">
                      <div className="loading-spinner"></div>
                      <span>Loading...</span>
                    </div>
                  </td>
                </tr>
              ) : processedData.length === 0 ? (
                <tr>
                  <td colSpan={columns.length} className="empty-cell">
                    {emptyMessage}
                  </td>
                </tr>
              ) : (
                processedData.map((item, index) => (
                  <tr key={index} className="data-row">
                    {columns.map(column => (
                      <td key={column.key as string}>
                        {column.renderCell 
                          ? column.renderCell(item, item[column.key])
                          : item[column.key]?.toString() || '-'
                        }
                      </td>
                    ))}
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Pagination */}
      {pagination && (
        <div className="datatable-pagination">
          <div className="pagination-info">
            Showing {((pagination.current - 1) * pagination.pageSize) + 1} to{' '}
            {Math.min(pagination.current * pagination.pageSize, pagination.total)} of{' '}
            {pagination.total} entries
          </div>
          
          <div className="pagination-controls">
            <button
              className="pagination-btn"
              disabled={pagination.current <= 1}
              onClick={() => pagination.onChange(pagination.current - 1, pagination.pageSize)}
            >
              Previous
            </button>
            
            <div className="page-numbers">
              {Array.from({ length: Math.ceil(pagination.total / pagination.pageSize) }, (_, i) => {
                const pageNum = i + 1;
                const isActive = pageNum === pagination.current;
                const isVisible = Math.abs(pageNum - pagination.current) <= 2 || 
                                pageNum === 1 || 
                                pageNum === Math.ceil(pagination.total / pagination.pageSize);
                
                if (!isVisible) return null;
                
                return (
                  <button
                    key={pageNum}
                    className={`page-number ${isActive ? 'active' : ''}`}
                    onClick={() => pagination.onChange(pageNum, pagination.pageSize)}
                  >
                    {pageNum}
                  </button>
                );
              })}
            </div>
            
            <button
              className="pagination-btn"
              disabled={pagination.current >= Math.ceil(pagination.total / pagination.pageSize)}
              onClick={() => pagination.onChange(pagination.current + 1, pagination.pageSize)}
            >
              Next
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

export default DataTable;