import { authService } from './authService';

export interface RatingValue {
  id: number;
  year: number;
  actualValue: number | string;
  projectedValue: number | string;
  textValue: string;
}

export interface RatingSubmission {
  departmentId?: string;
  facultyId?: string;
  cycle: string;
  category: string;
  values: Array<{
    parameterId: string;
    value: number | string;
    textValue?: string;
    justification?: string;
  }>;
  status: 'draft' | 'submitted';
}

export interface BulkRatingSubmission {
  ratings: RatingSubmission[];
}

export interface RatingStatistics {
  totalRatings: number;
  averageScore: number;
  maxScore: number;
  minScore: number;
  totalParameters: number;
  departmentCount: number;
  facultyCount: number;
  categoryCount: number;
  cycleCount: number;
}

export interface RatingFilters {
  departmentId?: string;
  facultyId?: string;
  cycle?: string;
  cycleId?: string;
  category?: string;
  categoryId?: string;
  status?: string;
  createdBy?: string;
  search?: string;
}

export interface PaginatedRatingResponse {
  data: any[];
  pagination: {
    page: number;
    pageSize: number;
    total: number;
    pages: number;
  };
}

class RatingService {
  // Get all ratings with filtering and pagination
  async getAllRatings(filters: RatingFilters = {}, page = 1, pageSize = 10): Promise<PaginatedRatingResponse> {
    try {
      const params = new URLSearchParams({
        page: page.toString(),
        pageSize: pageSize.toString(),
        ...filters
      });

      const response = await authService.axiosInstance.get(`/api/yearly-rating/all?${params.toString()}`);
      return response.data.Data;
    } catch (error: any) {
      throw new Error(error.response?.data?.Message || 'Failed to fetch ratings');
    }
  }

  // Get ratings by department (with cycle and category filtering)
  async getRatingsByDepartment(departmentId: string, filters: Partial<RatingFilters> = {}): Promise<any[]> {
    try {
      const params = new URLSearchParams();

      // Add filters to query params
      if (filters.cycleId) params.append('cycleId', filters.cycleId);
      if (filters.categoryId) params.append('categoryId', filters.categoryId);

      const queryString = params.toString();
      const url = `/api/yearly-rating/by-department/${departmentId}${queryString ? `?${queryString}` : ''}`;

      console.log('📊 Fetching ratings:', url);

      const response = await authService.axiosInstance.get(url);
      return response.data.Data;
    } catch (error: any) {
      throw new Error(error.response?.data?.Message || 'Failed to fetch department ratings');
    }
  }

  // Get rating statistics
  async getRatingStatistics(filters: Partial<RatingFilters> = {}): Promise<RatingStatistics> {
    try {
      const params = new URLSearchParams(filters as any);
      const response = await authService.axiosInstance.get(`/api/yearly-rating/statistics?${params.toString()}`);
      return response.data.Data;
    } catch (error: any) {
      throw new Error(error.response?.data?.Message || 'Failed to fetch rating statistics');
    }
  }

  // Submit single rating
  async createRating(rating: RatingSubmission): Promise<any> {
    try {
      const response = await authService.axiosInstance.post('/api/yearly-rating', rating);
      return response.data.Data;
    } catch (error: any) {
      throw new Error(error.response?.data?.Message || 'Failed to create rating');
    }
  }

  // Submit multiple ratings at once
  async bulkSubmitRatings(ratingsData: BulkRatingSubmission): Promise<any> {
    try {
      const response = await authService.axiosInstance.post('/api/yearly-rating/bulk-submit', ratingsData);
      return response.data.Data;
    } catch (error: any) {
      throw new Error(error.response?.data?.Message || 'Failed to submit ratings');
    }
  }

  // Update existing rating
  async updateRating(ratingId: string, rating: Partial<RatingSubmission>): Promise<any> {
    try {
      const response = await authService.axiosInstance.put(`/api/yearly-rating/${ratingId}`, rating);
      return response.data.Data;
    } catch (error: any) {
      throw new Error(error.response?.data?.Message || 'Failed to update rating');
    }
  }

  // Delete rating
  async deleteRating(ratingId: string): Promise<void> {
    try {
      await authService.axiosInstance.delete(`/api/yearly-rating/${ratingId}`);
    } catch (error: any) {
      throw new Error(error.response?.data?.Message || 'Failed to delete rating');
    }
  }

  // Get rating by ID
  async getRatingById(ratingId: string): Promise<any> {
    try {
      const response = await authService.axiosInstance.get(`/api/yearly-rating/${ratingId}`);
      return response.data.Data;
    } catch (error: any) {
      throw new Error(error.response?.data?.Message || 'Failed to fetch rating');
    }
  }

  // Submit rating (change status to submitted)
  async submitRating(ratingId: string): Promise<any> {
    try {
      const response = await authService.axiosInstance.post(`/api/yearly-rating/submit/${ratingId}`);
      return response.data.Data;
    } catch (error: any) {
      throw new Error(error.response?.data?.Message || 'Failed to submit rating');
    }
  }

  // Get distinct values for filtering
  async getDistinctValues(field: 'cycle' | 'category' | 'status'): Promise<string[]> {
    try {
      const response = await authService.axiosInstance.get(`/api/yearly-rating/distinct/${field}`);
      return response.data.Data;
    } catch (error: any) {
      throw new Error(error.response?.data?.Message || 'Failed to fetch distinct values');
    }
  }

  // Export ratings to Excel
  async exportRatings(filters: Partial<RatingFilters> = {}): Promise<Blob> {
    try {
      const params = new URLSearchParams(filters as any);
      const response = await authService.axiosInstance.get(`/api/yearly-rating/export?${params.toString()}`, {
        responseType: 'blob'
      });
      return response.data;
    } catch (error: any) {
      throw new Error(error.response?.data?.Message || 'Failed to export ratings');
    }
  }

  // Generate comprehensive report
  async generateComprehensiveReport(filters: Partial<RatingFilters> = {}): Promise<any> {
    try {
      const params = new URLSearchParams(filters as any);
      const response = await authService.axiosInstance.get(`/api/yearly-rating/reports/comprehensive?${params.toString()}`);
      return response.data.Data;
    } catch (error: any) {
      throw new Error(error.response?.data?.Message || 'Failed to generate comprehensive report');
    }
  }

  // Generate department performance report
  async generateDepartmentPerformanceReport(filters: Partial<RatingFilters> = {}): Promise<any> {
    try {
      const params = new URLSearchParams(filters as any);
      const response = await authService.axiosInstance.get(`/api/yearly-rating/reports/department-performance?${params.toString()}`);
      return response.data.Data;
    } catch (error: any) {
      throw new Error(error.response?.data?.Message || 'Failed to generate department performance report');
    }
  }

  // Generate faculty comparison report
  async generateFacultyComparisonReport(cycle: string): Promise<any> {
    try {
      const response = await authService.axiosInstance.get(`/api/yearly-rating/reports/faculty-comparison?cycle=${cycle}`);
      return response.data.Data;
    } catch (error: any) {
      throw new Error(error.response?.data?.Message || 'Failed to generate faculty comparison report');
    }
  }

  // Generate parameter utilization report
  async generateParameterUtilizationReport(filters: Partial<RatingFilters> = {}): Promise<any> {
    try {
      const params = new URLSearchParams(filters as any);
      const response = await authService.axiosInstance.get(`/api/yearly-rating/reports/parameter-utilization?${params.toString()}`);
      return response.data.Data;
    } catch (error: any) {
      throw new Error(error.response?.data?.Message || 'Failed to generate parameter utilization report');
    }
  }

  // Export report to Excel
  async exportReport(reportType: 'comprehensive' | 'department-performance' | 'faculty-comparison' | 'parameter-utilization', filters: any = {}): Promise<Blob> {
    try {
      const params = new URLSearchParams(filters);
      const response = await authService.axiosInstance.get(`/api/yearly-rating/reports/export/${reportType}?${params.toString()}`, {
        responseType: 'blob'
      });
      return response.data;
    } catch (error: any) {
      throw new Error(error.response?.data?.Message || 'Failed to export report');
    }
  }

  // Get past ratings for a parameter (for pre-populating forms)
  async getPastRatings(parameterId: string, category?: string): Promise<RatingValue[]> {
    try {
      // This will fetch existing ratings for a parameter to pre-populate the form
      const response = await authService.axiosInstance.get(`/api/yearly-rating/by-parameter/${parameterId}?category=${category || ''}`);
      return response.data.Data;
    } catch (error: any) {
      // Return empty array if no past ratings found
      console.warn('No past ratings found for parameter:', parameterId);
      return [];
    }
  }

  // Get past ratings by category (for form initialization - matching Angular workflow)
  async getPastRatingsByCategory(categoryName: string): Promise<any[]> {
    try {
      // This endpoint matches the Angular implementation: yearly-rating?categoryName=
      const response = await authService.axiosInstance.get(`/api/yearly-rating?categoryName=${categoryName}`);
      return response.data.Data || [];
    } catch (error: any) {
      // Return empty array if no past ratings found
      console.warn('No past ratings found for category:', categoryName);
      return [];
    }
  }

  // Submit target values for all cycle years (batch, immutable once saved)
  async submitTargetValues(
    parameterId: number,
    targetValues: { year: number; value: number | string }[],
    overallTarget: number | null
  ): Promise<{ Status: boolean; Data?: any; Message: string }> {
    try {
      const response = await authService.axiosInstance.post('/api/yearly-rating/submit-targets', {
        parameterId,
        targetValues,
        overallTarget
      });
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        return {
          Status: false,
          Message: error.response.data.Message
        };
      }
      return {
        Status: false,
        Message: 'Failed to submit target values'
      };
    }
  }

  // Submit individual parameter for specific cycle
  async submitIndividualParameter(
    parameterId: number,
    cycle: number,
    values: {
      actualValue?: number;
      projectedValue?: number;
      textValue?: string;
    }
  ): Promise<{Status: boolean, Data?: any, Message: string}> {
    try {
      const response = await authService.axiosInstance.post('/api/yearly-rating/submit-parameter', {
        parameterId,
        cycle,
        values
      });
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        return {
          Status: false,
          Message: error.response.data.Message
        };
      }
      return {
        Status: false,
        Message: 'Failed to submit parameter'
      };
    }
  }
}

export const ratingService = new RatingService();