import React, { useState, useEffect } from 'react';
import { Settings, Edit3, BarChart3, Users, FileText, Calendar, Archive, Trash2 } from 'lucide-react';
import { Button } from '../ui/button';
import { Input } from '../ui/input';
import { Label } from '../ui/label';
import { Badge } from '../ui/badge';
import { Progress } from '../ui/progress';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '../ui/dialog';
import { Alert, AlertDescription } from '../ui/alert';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '../ui/tabs';
import { Cycle, CycleUpdateRequest, CycleAnalytics, CycleStatistics } from '../../types/cycle.types';
import { cycleService } from '../../services/cycleService';
import { toast } from '../../hooks/use-toast';

interface CycleDetailsModalProps {
  isOpen: boolean;
  onClose: () => void;
  cycle: Cycle;
  onUpdate: () => void;
}

export const CycleDetailsModal: React.FC<CycleDetailsModalProps> = ({
  isOpen,
  onClose,
  cycle,
  onUpdate
}) => {
  const [activeTab, setActiveTab] = useState('details');
  const [editMode, setEditMode] = useState(true);
  const [analytics, setAnalytics] = useState<CycleAnalytics | null>(null);
  const [statistics, setStatistics] = useState<CycleStatistics | null>(null);
  const [submitting, setSubmitting] = useState(false);

  const [formData, setFormData] = useState<CycleUpdateRequest>({
    name: cycle.name,
    cycleName: cycle.cycleName,
    description: cycle.description,
    startYear: cycle.startYear,
    endYear: cycle.endYear
  });

  useEffect(() => {
    if (isOpen && cycle) {
      setFormData({
        name: cycle.name,
        cycleName: cycle.cycleName,
        description: cycle.description,
        startYear: cycle.startYear,
        endYear: cycle.endYear
      });
      setEditMode(true);
      loadAnalytics();
      loadStatistics();
    }
  }, [isOpen, cycle]);

  const loadAnalytics = async () => {
    try {
      const data = await cycleService.getCycleAnalytics(cycle._id, true);
      setAnalytics(data);
    } catch (error) {
      console.error('Error loading analytics:', error);
    }
  };

  const loadStatistics = async () => {
    try {
      const data = await cycleService.getCycleStatistics(cycle._id);
      setStatistics(data);
    } catch (error) {
      console.error('Error loading statistics:', error);
    }
  };

  const handleSave = async () => {
    setSubmitting(true);
    try {
      await cycleService.updateCycle(cycle._id, formData);
      toast({
        title: "Success",
        description: "Cycle updated successfully"
      });
      setEditMode(false);
      onUpdate();
    } catch (error) {
      console.error('Error updating cycle:', error);
      toast({
        title: "Error",
        description: "Failed to update cycle",
        variant: "destructive"
      });
    } finally {
      setSubmitting(false);
    }
  };

  const handleArchive = async () => {
    if (!window.confirm('Are you sure you want to archive this cycle? This action cannot be undone.')) {
      return;
    }

    setSubmitting(true);
    try {
      await cycleService.archiveCycle(cycle._id, 'Archived from cycle details');
      toast({
        title: "Success",
        description: "Cycle archived successfully"
      });
      onUpdate();
      onClose();
    } catch (error) {
      console.error('Error archiving cycle:', error);
      toast({
        title: "Error",
        description: "Failed to archive cycle",
        variant: "destructive"
      });
    } finally {
      setSubmitting(false);
    }
  };

  const handleDelete = async () => {
    if (!window.confirm('Are you sure you want to delete this cycle? This action cannot be undone.')) {
      return;
    }

    setSubmitting(true);
    try {
      await cycleService.deleteCycle(cycle._id, 'Deleted from cycle details');
      toast({
        title: "Success",
        description: "Cycle deleted successfully"
      });
      onUpdate();
      onClose();
    } catch (error) {
      console.error('Error deleting cycle:', error);
      toast({
        title: "Error",
        description: "Failed to delete cycle",
        variant: "destructive"
      });
    } finally {
      setSubmitting(false);
    }
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString();
  };

  const getStatusBadge = () => {
    if (cycle.isActive) {
      return <Badge variant="success" className="bg-green-100 text-green-800">Active</Badge>;
    }

    switch (cycle.status) {
      case 'draft':
        return <Badge variant="secondary" className="bg-gray-100 text-gray-800">Draft</Badge>;
      case 'completed':
        return <Badge variant="default" className="bg-blue-100 text-blue-800">Completed</Badge>;
      case 'archived':
        return <Badge variant="destructive" className="bg-red-100 text-red-800">Archived</Badge>;
      default:
        return <Badge variant="outline">Unknown</Badge>;
    }
  };

  // Safety check - ensure cycle has required properties
  if (!cycle || !cycle.cycleName) {
    return (
      <Dialog open={isOpen} onOpenChange={onClose}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Loading...</DialogTitle>
          </DialogHeader>
          <div className="p-4 text-center">Loading cycle details...</div>
        </DialogContent>
      </Dialog>
    );
  }

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Settings className="h-5 w-5" />
            {cycle.cycleName} - Details
          </DialogTitle>
        </DialogHeader>

        <div className="w-full">
          {/* Details Section */}
          <div className="space-y-6">
            <div className="flex justify-between items-center">
              <div className="flex items-center gap-3">
                <h2 className="text-xl font-semibold">{cycle.cycleName}</h2>
                {getStatusBadge()}
              </div>
              <div className="flex gap-2">
                {!editMode ? (
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setEditMode(true)}
                    disabled={cycle.status === 'archived'}
                  >
                    <Edit3 className="h-4 w-4 mr-1" />
                    Edit
                  </Button>
                ) : (
                  <div className="flex gap-2">
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => setEditMode(false)}
                      disabled={submitting}
                    >
                      Cancel
                    </Button>
                    <Button
                      size="sm"
                      onClick={handleSave}
                      disabled={submitting}
                    >
                      {submitting ? 'Saving...' : 'Save'}
                    </Button>
                  </div>
                )}
              </div>
            </div>

            {editMode ? (
              <div className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <Label htmlFor="name">Internal Name</Label>
                    <Input
                      id="name"
                      value={formData.name}
                      onChange={(e) => setFormData(prev => ({ ...prev, name: e.target.value }))}
                    />
                  </div>
                  <div>
                    <Label htmlFor="cycleName">Display Name</Label>
                    <Input
                      id="cycleName"
                      value={formData.cycleName}
                      onChange={(e) => setFormData(prev => ({ ...prev, cycleName: e.target.value }))}
                    />
                  </div>
                </div>

                <div>
                  <Label htmlFor="description">Description</Label>
                  <textarea
                    id="description"
                    value={formData.description || ''}
                    onChange={(e) => setFormData(prev => ({ ...prev, description: e.target.value }))}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                    rows={3}
                  />
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <Label htmlFor="startYear">Start Year</Label>
                    <Input
                      id="startYear"
                      type="date"
                      value={formData.startYear}
                      onChange={(e) => setFormData(prev => ({ ...prev, startYear: e.target.value }))}
                    />
                  </div>
                  <div>
                    <Label htmlFor="endYear">End Year</Label>
                    <Input
                      id="endYear"
                      type="date"
                      value={formData.endYear}
                      onChange={(e) => setFormData(prev => ({ ...prev, endYear: e.target.value }))}
                    />
                  </div>
                </div>
              </div>
            ) : (
              <div className="space-y-6">
                {/* Basic Information */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-4">
                    <div>
                      <h3 className="font-medium text-gray-900">Basic Information</h3>
                      <div className="mt-2 space-y-2 text-sm">
                        <div><span className="text-gray-500">Internal Name:</span> {cycle.name}</div>
                        <div><span className="text-gray-500">Display Name:</span> {cycle.cycleName}</div>
                        <div><span className="text-gray-500">Description:</span> {cycle.description || 'No description'}</div>
                      </div>
                    </div>

                    <div>
                      <h3 className="font-medium text-gray-900">Timeline</h3>
                      <div className="mt-2 space-y-2 text-sm">
                        <div><span className="text-gray-500">Year Range:</span> {cycle.yearRange}</div>
                        <div><span className="text-gray-500">Start Year:</span> {formatDate(cycle.startYear)}</div>
                        <div><span className="text-gray-500">End Year:</span> {formatDate(cycle.endYear)}</div>
                        <div><span className="text-gray-500">Duration:</span> {cycle.cycleYears?.length || 0} years</div>
                      </div>
                    </div>
                  </div>

                  <div className="space-y-4">
                    <div>
                      <h3 className="font-medium text-gray-900">Current Status</h3>
                      <div className="mt-2 space-y-2 text-sm">
                        <div>
                          <span className="text-gray-500">Current Active Year:</span>
                          {cycle.currentActiveYear ? (
                            <Badge variant="outline" className="ml-2">{cycle.currentActiveYear}</Badge>
                          ) : (
                            <span className="ml-2 text-gray-400">Not set</span>
                          )}
                        </div>
                        <div>
                          <span className="text-gray-500">Target Year:</span>
                          {cycle.targetYear ? (
                            <Badge variant="outline" className="ml-2">{cycle.targetYear}</Badge>
                          ) : (
                            <span className="ml-2 text-gray-400">Not set</span>
                          )}
                        </div>
                        <div>
                          <span className="text-gray-500">Progress:</span>
                          <div className="mt-1">
                            <Progress value={cycle.progressPercentage || 0} className="h-2" />
                            <span className="text-xs text-gray-500">{cycle.progressPercentage || 0}% Complete</span>
                          </div>
                        </div>
                      </div>
                    </div>

                    <div>
                      <h3 className="font-medium text-gray-900">Parameters</h3>
                      <div className="mt-2 space-y-2 text-sm">
                        <div><span className="text-gray-500">Total Parameters:</span> {cycle.totalParameters ?? 0}</div>
                        <div><span className="text-gray-500">Active Parameters:</span> {cycle.activeParameters ?? 0}</div>
                      </div>
                    </div>
                  </div>
                </div>

                {/* Year Activation Status */}
                <div>
                  <h3 className="font-medium text-gray-900 mb-3">Year Activation Status</h3>
                  <div className="grid grid-cols-4 gap-3">
                    {cycle.cycleYears.map((year) => {
                      const yearData = cycle.yearActivation?.[year];
                      const isActive = yearData?.isActive || false;
                      const projectionEnabled = yearData?.projectionSubmissionsEnabled || false;
                      const actualEnabled = yearData?.actualSubmissionsEnabled || false;

                      return (
                        <div
                          key={year}
                          className={`p-3 border rounded-lg text-center ${
                            isActive ? 'border-green-500 bg-green-50' : 'border-gray-200'
                          }`}
                        >
                          <div className="font-medium">{year}</div>
                          <div className="text-xs mt-1">
                            {isActive ? (
                              <div className="space-y-1">
                                <Badge variant="success" className="text-xs">Active</Badge>
                                {projectionEnabled && <div className="text-blue-600">Projected ✓</div>}
                                {actualEnabled && <div className="text-green-600">Actual ✓</div>}
                              </div>
                            ) : (
                              <Badge variant="secondary" className="text-xs">Inactive</Badge>
                            )}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              </div>
            )}

            {/* Action Buttons */}
            {!editMode && cycle.status !== 'archived' && (
              <div className="flex justify-end space-x-3 pt-4 border-t">
                <Button
                  variant="outline"
                  onClick={handleArchive}
                  disabled={submitting}
                  className="text-orange-600 hover:text-orange-700"
                >
                  <Archive className="h-4 w-4 mr-1" />
                  Archive
                </Button>
                {cycle.status === 'draft' && (
                  <Button
                    variant="destructive"
                    onClick={handleDelete}
                    disabled={submitting}
                  >
                    <Trash2 className="h-4 w-4 mr-1" />
                    Delete
                  </Button>
                )}
              </div>
            )}
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
};

// Removed Analytics, Statistics, and Audit tabs - keeping only Details/Edit view

export default CycleDetailsModal;
