import { apiClient } from './apiClient';
import {
  Cycle,
  CycleCreateRequest,
  CycleUpdateRequest,
  CycleAnalytics,
  CycleStatistics,
  YearActivationRequest,
  TargetYearEnableRequest,
  PaginatedResponse,
  ApiResponse
} from '../types/cycle.types';

// Enhanced Cycle Management Service
// 🎯 PURPOSE: Complete service layer for dynamic cycle management

class CycleService {
  private baseUrl = '/api/cycles';

  // Get all cycles with filtering and pagination
  async getAllCycles(params?: {
    page?: number;
    limit?: number;
    status?: string;
    isActive?: boolean;
    year?: number;
    search?: string;
    sortBy?: string;
    sortOrder?: 'asc' | 'desc';
  }): Promise<PaginatedResponse<Cycle>> {
    const queryParams = new URLSearchParams();

    if (params) {
      Object.entries(params).forEach(([key, value]) => {
        if (value !== undefined && value !== null) {
          queryParams.append(key, value.toString());
        }
      });
    }

    const response = await apiClient.get<PaginatedResponse<Cycle>>(
      `${this.baseUrl}?${queryParams.toString()}`
    );
    return response.data;
  }

  // Get active cycle
  async getActiveCycle(includeParameters = false): Promise<Cycle | null> {
    try {
      const response = await apiClient.get<ApiResponse<Cycle>>(
        `${this.baseUrl}/active?includeParameters=${includeParameters}`
      );
      return response.data.data;
    } catch (error: any) {
      if (error.response?.status === 404) {
        return null; // No active cycle found
      }
      throw error;
    }
  }

  // Get cycle by ID
  async getCycleById(
    id: number,
    includeParameters = false,
    includeStats = false
  ): Promise<Cycle> {
    const params = new URLSearchParams();
    if (includeParameters) params.append('includeParameters', 'true');
    if (includeStats) params.append('includeStats', 'true');

    const response = await apiClient.get<ApiResponse<Cycle>>(
      `${this.baseUrl}/${id}?${params.toString()}`
    );
    return response.data.data;
  }

  // Create new cycle
  async createCycle(cycleData: CycleCreateRequest): Promise<Cycle> {
    const response = await apiClient.post<ApiResponse<Cycle>>(
      this.baseUrl,
      cycleData
    );
    return response.data.data;
  }

  // Update existing cycle
  async updateCycle(id: number, updateData: CycleUpdateRequest): Promise<Cycle> {
    const response = await apiClient.put<ApiResponse<Cycle>>(
      `${this.baseUrl}/${id}`,
      updateData
    );
    return response.data.data;
  }

  // Activate specific year in cycle
  async activateYear(id: number, request: YearActivationRequest): Promise<void> {
    await apiClient.post(`${this.baseUrl}/${id}/activate-year`, request);
  }

  // Batch activate multiple years in cycle
  async batchActivateYears(id: number, request: {
    years: number[];
    targetYearProjections?: boolean;
    reason?: string;
  }): Promise<any> {
    const response = await apiClient.post(`${this.baseUrl}/${id}/batch-activate-years`, request);
    return response.data;
  }

  // Enable target year actual submissions
  async enableTargetYearSubmissions(
    id: number,
    request: TargetYearEnableRequest
  ): Promise<void> {
    await apiClient.post(`${this.baseUrl}/${id}/enable-target-submissions`, request);
  }

  // Get cycle analytics
  async getCycleAnalytics(
    id: number,
    includeComparisons = false
  ): Promise<CycleAnalytics> {
    const response = await apiClient.get<ApiResponse<CycleAnalytics>>(
      `${this.baseUrl}/${id}/analytics?includeComparisons=${includeComparisons}`
    );
    return response.data.data;
  }

  // Get cycle statistics
  async getCycleStatistics(id: number): Promise<CycleStatistics> {
    const response = await apiClient.get<ApiResponse<CycleStatistics>>(
      `${this.baseUrl}/${id}/statistics`
    );
    return response.data.data;
  }

  // Duplicate cycle
  async duplicateCycle(
    sourceId: number,
    newCycleData: CycleCreateRequest & { copyParameters?: boolean }
  ): Promise<Cycle> {
    const response = await apiClient.post<ApiResponse<Cycle>>(
      `${this.baseUrl}/${sourceId}/duplicate`,
      newCycleData
    );
    return response.data.data;
  }

  // Archive cycle
  async archiveCycle(id: number, reason?: string): Promise<void> {
    await apiClient.put(`${this.baseUrl}/${id}/archive`, { reason });
  }

  // Restore archived cycle
  async restoreCycle(id: number): Promise<void> {
    await apiClient.put(`${this.baseUrl}/${id}/restore`);
  }

  // Soft delete cycle
  async deleteCycle(id: number, reason?: string): Promise<void> {
    await apiClient.delete(`${this.baseUrl}/${id}`, { data: { reason } });
  }

  // Get cycle audit trail
  async getCycleAudit(
    id: number,
    params?: {
      limit?: number;
      startDate?: string;
      endDate?: string;
    }
  ): Promise<any[]> {
    const queryParams = new URLSearchParams();
    if (params) {
      Object.entries(params).forEach(([key, value]) => {
        if (value !== undefined) {
          queryParams.append(key, value.toString());
        }
      });
    }

    const response = await apiClient.get<ApiResponse<{ auditTrail: any[] }>>(
      `${this.baseUrl}/${id}/audit?${queryParams.toString()}`
    );
    return response.data.data.auditTrail;
  }

  // Get performance metrics
  async getPerformanceMetrics(id: number, year?: number): Promise<any> {
    const params = year ? `?year=${year}` : '';
    const response = await apiClient.get<ApiResponse<any>>(
      `${this.baseUrl}/${id}/performance${params}`
    );
    return response.data.data;
  }

  // Utility methods
  async validateCycleName(name: string, excludeId?: number): Promise<boolean> {
    try {
      const cycles = await this.getAllCycles({ search: name, limit: 1 });
      const existing = cycles.data.cycles.find(c =>
        c.name.toLowerCase() === name.toLowerCase() && c._id !== excludeId
      );
      return !existing; // Return true if name is available
    } catch (error) {
      console.error('Error validating cycle name:', error);
      return false;
    }
  }

  async getCycleYearRange(startYear: string, endYear: string): Promise<number[]> {
    const start = new Date(startYear).getFullYear();
    const end = new Date(endYear).getFullYear();
    const years: number[] = [];

    for (let year = start; year <= end; year++) {
      years.push(year);
    }

    return years;
  }

  async getCurrentCycleYear(): Promise<number | null> {
    try {
      const activeCycle = await this.getActiveCycle();
      return activeCycle?.currentActiveYear || null;
    } catch (error) {
      console.error('Error getting current cycle year:', error);
      return null;
    }
  }

  // Check if user can perform cycle operations
  async canManageCycles(): Promise<boolean> {
    // This would check user permissions - implement based on auth context
    return true; // Placeholder
  }

  // Format cycle for display
  formatCycleForDisplay(cycle: Cycle): {
    displayName: string;
    yearRange: string;
    statusBadge: string;
    progressText: string;
  } {
    return {
      displayName: cycle.cycleName || cycle.name,
      yearRange: cycle.yearRange || `${new Date(cycle.startYear).getFullYear()}-${new Date(cycle.endYear).getFullYear()}`,
      statusBadge: this.getStatusBadgeText(cycle.status, cycle.isActive),
      progressText: `${cycle.progressPercentage || 0}% Complete`
    };
  }

  private getStatusBadgeText(status: string, isActive: boolean): string {
    if (isActive) return 'Active';

    switch (status) {
      case 'draft': return 'Draft';
      case 'completed': return 'Completed';
      case 'archived': return 'Archived';
      default: return 'Unknown';
    }
  }

  // Get cycles for dropdown/select
  async getCyclesForSelect(): Promise<Array<{ value: number; label: string }>> {
    try {
      const response = await this.getAllCycles({ limit: 100 });
      return response.data.cycles.map(cycle => ({
        value: cycle._id,
        label: this.formatCycleForDisplay(cycle).displayName
      }));
    } catch (error) {
      console.error('Error getting cycles for select:', error);
      return [];
    }
  }

  // Real-time updates (WebSocket integration placeholder)
  subscribeToUpdates(cycleId: number, callback: (update: any) => void): () => void {
    // Placeholder for WebSocket subscription
    // Implementation would depend on WebSocket setup
    console.log(`Subscribing to updates for cycle ${cycleId}`);

    // Return unsubscribe function
    return () => {
      console.log(`Unsubscribing from updates for cycle ${cycleId}`);
    };
  }

  // Batch operations
  async batchUpdateCycles(updates: Array<{id: number, data: Partial<CycleUpdateRequest>}>): Promise<void> {
    const promises = updates.map(update =>
      this.updateCycle(update.id, update.data)
    );

    await Promise.allSettled(promises);
  }

  // Export cycle data
  async exportCycleData(
    id: number,
    format: 'json' | 'csv' = 'json'
  ): Promise<Blob> {
    const response = await apiClient.get(
      `/api/analytics/export?type=cycle&cycleId=${id}&format=${format}`,
      { responseType: 'blob' }
    );
    return response.data;
  }
}

// Export singleton instance
export const cycleService = new CycleService();
export default cycleService;