import React, { useState, useEffect } from 'react';
import { Plus, Search, Filter, Calendar, Settings, BarChart3, Archive, Trash2, Edit } from 'lucide-react';
import { Button } from '../../../components/ui/button';
import { Input } from '../../../components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '../../../components/ui/card';
import { Badge } from '../../../components/ui/badge';
import { Progress } from '../../../components/ui/progress';
import DataTable from '../../../components/data-table/DataTable';
import { Cycle } from '../../../types/cycle.types';
import { cycleService } from '../../../services/cycleService';
import { toast } from '../../../hooks/use-toast';
import { CreateCycleModal } from '../../../components/cycle-modals/CreateCycleModal';
import { CycleDetailsModal } from '../../../components/cycle-modals/CycleDetailsModal';
import { YearActivationModal } from '../../../components/cycle-modals/YearActivationModal';
import './CycleManagement.css';

interface CycleManagementProps {}

export const CycleManagement: React.FC<CycleManagementProps> = () => {
  const [cycles, setCycles] = useState<Cycle[]>([]);
  const [activeCycle, setActiveCycle] = useState<Cycle | null>(null);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [selectedCycle, setSelectedCycle] = useState<Cycle | null>(null);

  // Modal states
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showDetailsModal, setShowDetailsModal] = useState(false);
  const [showYearActivationModal, setShowYearActivationModal] = useState(false);

  // Pagination
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [pageSize, setPageSize] = useState(10);
  const [totalCycles, setTotalCycles] = useState(0);
  const itemsPerPage = 10;

  useEffect(() => {
    loadCycles();
    loadActiveCycle();
  }, [currentPage, searchTerm, statusFilter]);

  const loadCycles = async () => {
    try {
      setLoading(true);
      const params = {
        page: currentPage,
        limit: itemsPerPage,
        search: searchTerm || undefined,
        status: statusFilter !== 'all' ? statusFilter : undefined,
        sortBy: 'createdAt',
        sortOrder: 'desc' as const
      };

      const response = await cycleService.getAllCycles(params);
      setCycles(response.data.cycles);
      setTotalPages(response.data.pagination.totalPages);
      setTotalCycles(response.data.pagination.totalItems || response.data.cycles.length);
    } catch (error) {
      console.error('Error loading cycles:', error);
      toast({
        title: "Error",
        description: "Failed to load cycles",
        variant: "destructive"
      });
    } finally {
      setLoading(false);
    }
  };

  const loadActiveCycle = async () => {
    try {
      const active = await cycleService.getActiveCycle(true);
      setActiveCycle(active);
    } catch (error) {
      console.error('Error loading active cycle:', error);
    }
  };

  const handleCreateCycle = async (cycleData: any) => {
    try {
      await cycleService.createCycle(cycleData);
      toast({
        title: "Success",
        description: "Cycle created successfully"
      });
      setShowCreateModal(false);
      loadCycles();
    } catch (error) {
      console.error('Error creating cycle:', error);
      toast({
        title: "Error",
        description: "Failed to create cycle",
        variant: "destructive"
      });
    }
  };

  const handleActivateCycle = async (cycleId: number) => {
    try {
      await cycleService.updateCycle(cycleId, { isActive: true });
      toast({
        title: "Success",
        description: "Cycle activated successfully"
      });
      loadCycles();
      loadActiveCycle();
    } catch (error) {
      console.error('Error activating cycle:', error);
      toast({
        title: "Error",
        description: "Failed to activate cycle",
        variant: "destructive"
      });
    }
  };

  const handleArchiveCycle = async (cycleId: number, reason?: string) => {
    try {
      await cycleService.archiveCycle(cycleId, reason);
      toast({
        title: "Success",
        description: "Cycle archived successfully"
      });
      loadCycles();
      loadActiveCycle();
    } catch (error) {
      console.error('Error archiving cycle:', error);
      toast({
        title: "Error",
        description: "Failed to archive cycle",
        variant: "destructive"
      });
    }
  };

  const handleDeactivateCycle = async (cycleId: number) => {
    try {
      await cycleService.updateCycle(cycleId, { isActive: false });
      toast({
        title: "Success",
        description: "Cycle deactivated successfully"
      });
      loadCycles();
      loadActiveCycle();
    } catch (error) {
      console.error('Error deactivating cycle:', error);
      toast({
        title: "Error",
        description: "Failed to deactivate cycle",
        variant: "destructive"
      });
    }
  };

  const handleUnarchiveCycle = async (cycleId: number) => {
    try {
      await cycleService.updateCycle(cycleId, { status: 'draft' });
      toast({
        title: "Success",
        description: "Cycle unarchived successfully"
      });
      loadCycles();
      loadActiveCycle();
    } catch (error) {
      console.error('Error unarchiving cycle:', error);
      toast({
        title: "Error",
        description: "Failed to unarchive cycle",
        variant: "destructive"
      });
    }
  };

  const handleDeleteCycle = async (cycleId: number) => {
    if (!window.confirm('Are you sure you want to delete this cycle? This action cannot be undone.')) {
      return;
    }

    try {
      await cycleService.deleteCycle(cycleId, 'Deleted by admin');
      toast({
        title: "Success",
        description: "Cycle deleted successfully"
      });
      loadCycles();
      loadActiveCycle();
    } catch (error) {
      console.error('Error deleting cycle:', error);
      toast({
        title: "Error",
        description: "Failed to delete cycle",
        variant: "destructive"
      });
    }
  };

  const getStatusBadge = (cycle: Cycle) => {
    const { status, isActive } = cycle;

    if (isActive) {
      return <Badge variant="success" className="bg-green-100 text-green-800">Active</Badge>;
    }

    switch (status) {
      case 'draft':
        return <Badge variant="secondary" className="bg-gray-100 text-gray-800">Draft</Badge>;
      case 'completed':
        return <Badge variant="default" className="bg-blue-100 text-blue-800">Completed</Badge>;
      case 'archived':
        return <Badge variant="destructive" className="bg-red-100 text-red-800">Archived</Badge>;
      default:
        return <Badge variant="outline">Unknown</Badge>;
    }
  };

  const formatYearRange = (cycle: Cycle) => {
    return cycle.yearRange || `${new Date(cycle.startYear).getFullYear()}-${new Date(cycle.endYear).getFullYear()}`;
  };

  const columns = [
    {
      key: 'name' as keyof Cycle,
      label: 'Cycle Name',
      renderCell: (cycle: Cycle) => (
        <div>
          <div className="font-medium">{cycle.cycleName || cycle.name}</div>
          <div className="text-sm text-gray-500">{formatYearRange(cycle)}</div>
        </div>
      )
    },
    {
      key: 'status' as keyof Cycle,
      label: 'Status',
      renderCell: (cycle: Cycle) => getStatusBadge(cycle)
    },
    {
      key: 'actions' as keyof Cycle,
      label: 'Actions',
      renderCell: (cycle: Cycle) => (
        <div className="flex space-x-2">
          <Button
            variant="outline"
            size="sm"
            onClick={() => {
              setSelectedCycle(cycle);
              setShowDetailsModal(true);
            }}
            title="Edit Cycle"
          >
            <Edit className="h-4 w-4" />
          </Button>
          {cycle.isActive && (
            <Button
              variant="outline"
              size="sm"
              onClick={() => {
                setSelectedCycle(cycle);
                setShowYearActivationModal(true);
              }}
            >
              <Calendar className="h-4 w-4" />
            </Button>
          )}
          {!cycle.isActive && cycle.status === 'draft' && (
            <Button
              variant="outline"
              size="sm"
              onClick={() => handleActivateCycle(cycle._id)}
            >
              Activate
            </Button>
          )}
          {cycle.isActive && (
            <Button
              variant="outline"
              size="sm"
              onClick={() => handleDeactivateCycle(cycle._id)}
              className="text-orange-600 hover:text-orange-700"
            >
              Deactivate
            </Button>
          )}
          {cycle.status === 'archived' ? (
            <Button
              variant="outline"
              size="sm"
              onClick={() => handleUnarchiveCycle(cycle._id)}
              className="text-green-600 hover:text-green-700"
            >
              Unarchive
            </Button>
          ) : (
            <Button
              variant="outline"
              size="sm"
              onClick={() => handleArchiveCycle(cycle._id)}
            >
              <Archive className="h-4 w-4" />
            </Button>
          )}
          <Button
            variant="outline"
            size="sm"
            onClick={() => handleDeleteCycle(cycle._id)}
            className="text-red-600 hover:text-red-700"
          >
            <Trash2 className="h-4 w-4" />
          </Button>
        </div>
      )
    }
  ];

  return (
    <div className="cycle-management">
      {/* Header Section */}
      <div className="flex justify-between items-center mb-6">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Cycle Management</h1>
          <p className="text-gray-600">Manage dynamic strategic planning cycles</p>
        </div>
        <Button onClick={() => setShowCreateModal(true)} className="flex items-center gap-2">
          <Plus className="h-4 w-4" />
          Create New Cycle
        </Button>
      </div>

      {/* Active Cycle Overview */}
      {activeCycle && (
        <Card className="mb-6 border-blue-200 bg-blue-50">
          <CardContent className="pt-6">
            <div className="flex items-center gap-2 text-blue-800">
              <BarChart3 className="h-5 w-5" />
              <span className="text-lg font-semibold">Active Cycle: {activeCycle.cycleName}</span>
            </div>
          </CardContent>
        </Card>
      )}


      {/* Cycles Table */}
      <Card>
        <CardContent className="pt-6">
          <DataTable
            data={cycles}
            columns={columns}
            loading={loading}
            pagination={{
              current: currentPage,
              pageSize: pageSize,
              total: totalCycles,
              onChange: (page: number, size: number) => {
                setCurrentPage(page);
                setPageSize(size);
              }
            }}
          />
        </CardContent>
      </Card>

      {/* Modals */}
      {showCreateModal && (
        <CreateCycleModal
          isOpen={showCreateModal}
          onClose={() => setShowCreateModal(false)}
          onSubmit={handleCreateCycle}
        />
      )}

      {showDetailsModal && selectedCycle && (
        <CycleDetailsModal
          isOpen={showDetailsModal}
          onClose={() => {
            setShowDetailsModal(false);
            setSelectedCycle(null);
          }}
          cycle={selectedCycle}
          onUpdate={loadCycles}
        />
      )}

      {showYearActivationModal && selectedCycle && (
        <YearActivationModal
          isOpen={showYearActivationModal}
          onClose={() => {
            setShowYearActivationModal(false);
            setSelectedCycle(null);
          }}
          cycle={selectedCycle}
          onActivate={loadCycles}
        />
      )}
    </div>
  );
};

export default CycleManagement;