import React, { useState, useEffect } from 'react';
import { X, Calendar, Copy, AlertCircle } from 'lucide-react';
import { Button } from '../ui/button';
import { Input } from '../ui/input';
import { Label } from '../ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../ui/select';
import { Checkbox } from '../ui/checkbox';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '../ui/dialog';
import { Alert, AlertDescription } from '../ui/alert';
import { CycleCreateRequest } from '../../types/cycle.types';
import { cycleService } from '../../services/cycleService';
import { toast } from '../../hooks/use-toast';

interface CreateCycleModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (data: CycleCreateRequest) => Promise<void>;
}

export const CreateCycleModal: React.FC<CreateCycleModalProps> = ({
  isOpen,
  onClose,
  onSubmit
}) => {
  const [formData, setFormData] = useState<CycleCreateRequest>({
    name: '',
    cycleName: '',
    description: '',
    startYear: '',
    endYear: '',
    copyParametersFrom: undefined
  });

  const [availableCycles, setAvailableCycles] = useState<Array<{ value: number; label: string }>>([]);
  const [copyParameters, setCopyParameters] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});

  useEffect(() => {
    if (isOpen) {
      loadAvailableCycles();
      resetForm();
    }
  }, [isOpen]);

  const loadAvailableCycles = async () => {
    try {
      const cycles = await cycleService.getCyclesForSelect();
      setAvailableCycles(cycles);
    } catch (error) {
      console.error('Error loading cycles:', error);
    }
  };

  const resetForm = () => {
    setFormData({
      name: '',
      cycleName: '',
      description: '',
      startYear: '',
      endYear: '',
      copyParametersFrom: undefined
    });
    setCopyParameters(false);
    setErrors({});
  };

  const validateForm = (): boolean => {
    const newErrors: Record<string, string> = {};

    if (!formData.name.trim()) {
      newErrors.name = 'Cycle name is required';
    }

    if (!formData.cycleName.trim()) {
      newErrors.cycleName = 'Display name is required';
    }

    if (!formData.startYear) {
      newErrors.startYear = 'Start year is required';
    }

    if (!formData.endYear) {
      newErrors.endYear = 'End year is required';
    }

    if (formData.startYear && formData.endYear) {
      const startYear = new Date(formData.startYear).getFullYear();
      const endYear = new Date(formData.endYear).getFullYear();

      if (endYear <= startYear) {
        newErrors.endYear = 'End year must be after start year';
      }

      if (endYear - startYear > 10) {
        newErrors.endYear = 'Cycle duration cannot exceed 10 years';
      }
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleInputChange = (field: keyof CycleCreateRequest, value: string | number) => {
    setFormData(prev => ({
      ...prev,
      [field]: value
    }));

    // Clear error for this field
    if (errors[field]) {
      setErrors(prev => {
        const newErrors = { ...prev };
        delete newErrors[field];
        return newErrors;
      });
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validateForm()) {
      return;
    }

    setSubmitting(true);
    try {
      const submitData = {
        ...formData,
        copyParametersFrom: copyParameters ? formData.copyParametersFrom : undefined
      };

      await onSubmit(submitData);
      onClose();
    } catch (error) {
      console.error('Error creating cycle:', error);
      toast({
        title: "Error",
        description: "Failed to create cycle",
        variant: "destructive"
      });
    } finally {
      setSubmitting(false);
    }
  };

  const generateYearRange = () => {
    if (formData.startYear && formData.endYear) {
      const startYear = new Date(formData.startYear).getFullYear();
      const endYear = new Date(formData.endYear).getFullYear();
      return `${startYear}-${endYear}`;
    }
    return '';
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Calendar className="h-5 w-5" />
            Create New Cycle
          </DialogTitle>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-6">
          {/* Basic Information */}
          <div className="space-y-4">
            <h3 className="text-lg font-medium">Basic Information</h3>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <Label htmlFor="name">Internal Name *</Label>
                <Input
                  id="name"
                  value={formData.name}
                  onChange={(e) => handleInputChange('name', e.target.value)}
                  placeholder="e.g., strategic-plan-2024-2029"
                  className={errors.name ? 'border-red-500' : ''}
                />
                {errors.name && (
                  <p className="text-sm text-red-500 mt-1">{errors.name}</p>
                )}
              </div>

              <div>
                <Label htmlFor="cycleName">Display Name *</Label>
                <Input
                  id="cycleName"
                  value={formData.cycleName}
                  onChange={(e) => handleInputChange('cycleName', e.target.value)}
                  placeholder="e.g., Strategic Plan 2024-2029"
                  className={errors.cycleName ? 'border-red-500' : ''}
                />
                {errors.cycleName && (
                  <p className="text-sm text-red-500 mt-1">{errors.cycleName}</p>
                )}
              </div>
            </div>

            <div>
              <Label htmlFor="description">Description</Label>
              <textarea
                id="description"
                value={formData.description}
                onChange={(e) => handleInputChange('description', e.target.value)}
                placeholder="Brief description of the cycle objectives and scope"
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                rows={3}
              />
            </div>
          </div>

          {/* Timeline Configuration */}
          <div className="space-y-4">
            <h3 className="text-lg font-medium">Timeline Configuration</h3>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <Label htmlFor="startYear">Start Year *</Label>
                <Input
                  id="startYear"
                  type="date"
                  value={formData.startYear}
                  onChange={(e) => handleInputChange('startYear', e.target.value)}
                  className={errors.startYear ? 'border-red-500' : ''}
                />
                {errors.startYear && (
                  <p className="text-sm text-red-500 mt-1">{errors.startYear}</p>
                )}
              </div>

              <div>
                <Label htmlFor="endYear">End Year *</Label>
                <Input
                  id="endYear"
                  type="date"
                  value={formData.endYear}
                  onChange={(e) => handleInputChange('endYear', e.target.value)}
                  className={errors.endYear ? 'border-red-500' : ''}
                />
                {errors.endYear && (
                  <p className="text-sm text-red-500 mt-1">{errors.endYear}</p>
                )}
              </div>
            </div>

            {generateYearRange() && (
              <Alert>
                <AlertCircle className="h-4 w-4" />
                <AlertDescription>
                  This cycle will span {generateYearRange()} ({
                    formData.startYear && formData.endYear
                      ? new Date(formData.endYear).getFullYear() - new Date(formData.startYear).getFullYear() + 1
                      : 0
                  } years)
                </AlertDescription>
              </Alert>
            )}
          </div>


          {/* Actions */}
          <div className="flex justify-end space-x-3 pt-4 border-t">
            <Button
              type="button"
              variant="outline"
              onClick={onClose}
              disabled={submitting}
            >
              Cancel
            </Button>
            <Button
              type="submit"
              disabled={submitting}
              className="min-w-[100px]"
            >
              {submitting ? 'Creating...' : 'Create Cycle'}
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
};

export default CreateCycleModal;