import React, { useState, useMemo } from 'react';
import { Loader2, ChevronUp, Lock, Target, BarChart3, TrendingUp, TrendingDown, AlertTriangle } from 'lucide-react';
import { ParameterDetails, FormValues, CycleInfo } from './ParameterListView';

interface ExpandableParameterFormProps {
  parameterDetails: ParameterDetails;
  onSubmit: (parameterId: number, cycle: number, values: FormValues) => Promise<boolean>;
  onSubmitTargets: (parameterId: number, targetValues: { year: number; value: number | string }[], overallTarget: number | null) => Promise<boolean>;
  onCollapse: () => void;
  isSubmitting: boolean;
}

const ExpandableParameterForm: React.FC<ExpandableParameterFormProps> = ({
  parameterDetails,
  onSubmit,
  onSubmitTargets,
  onCollapse,
  isSubmitting
}) => {
  const { parameter, allCycleYears, cycles, targetValuesLocked, overallTarget: savedOverallTarget, submittedValues } = parameterDetails;

  // Target values form state
  const [overallTargetInput, setOverallTargetInput] = useState<string>(
    savedOverallTarget !== null && savedOverallTarget !== undefined ? savedOverallTarget.toString() : ''
  );
  const [targetFormValues, setTargetFormValues] = useState<{ [year: number]: string }>({});
  const [targetErrors, setTargetErrors] = useState<string>('');

  // Actual values form state
  const [actualFormValues, setActualFormValues] = useState<{ [cycle: number]: FormValues }>({});
  const [actualErrors, setActualErrors] = useState<{ [cycle: number]: string }>({});
  const [isEditing, setIsEditing] = useState<{ [cycle: number]: boolean }>({});

  const isTextType = parameter.parameterType === 'Text';

  // --- TARGET VALUES SECTION ---

  const handleOverallTargetChange = (value: string) => {
    setOverallTargetInput(value);
    if (targetErrors) setTargetErrors('');
  };

  const handleTargetInputChange = (year: number, value: string) => {
    setTargetFormValues(prev => ({ ...prev, [year]: value }));
    if (targetErrors) setTargetErrors('');
  };

  const getTargetDisplayValue = (year: number): string => {
    // Only show submitted projected values when targets are locked (new-style submission)
    if (!targetValuesLocked) return '';
    const submitted = submittedValues[year];
    if (submitted) {
      if (isTextType && submitted.textValue) return submitted.textValue;
      if (submitted.projectedValue !== undefined && submitted.projectedValue !== null) {
        return submitted.projectedValue.toString();
      }
    }
    return '';
  };

  const getTargetInputValue = (year: number): string => {
    if (targetFormValues[year] !== undefined) return targetFormValues[year];
    return getTargetDisplayValue(year);
  };

  // Calculate the live sum of all yearly target inputs (numeric only)
  const getYearlySum = (): number => {
    let sum = 0;
    for (const year of allCycleYears) {
      const val = getTargetInputValue(year);
      const num = Number(val);
      if (!isNaN(num)) sum += num;
    }
    return sum;
  };

  const parsedOverallTarget = Number(overallTargetInput);
  const isOverallTargetValid = !isNaN(parsedOverallTarget) && parsedOverallTarget > 0;
  const yearlySum = isTextType ? 0 : getYearlySum();
  const remaining = isOverallTargetValid ? parsedOverallTarget - yearlySum : 0;
  const sumMatchesTarget = isOverallTargetValid && yearlySum === parsedOverallTarget;

  const handleSubmitAllTargets = async () => {
    const missing: number[] = [];
    const targetValues: { year: number; value: number | string }[] = [];

    // Validate overallTarget for numeric types
    if (!isTextType) {
      if (!overallTargetInput || !isOverallTargetValid) {
        setTargetErrors('Please enter a valid overall target value first.');
        return;
      }
      if (parsedOverallTarget > parameter.maxValue) {
        setTargetErrors(`Overall target cannot exceed the maximum value of ${parameter.maxValue}`);
        return;
      }
    }

    for (const year of allCycleYears) {
      const val = targetFormValues[year] !== undefined ? targetFormValues[year] : getTargetDisplayValue(year);

      if (!val && val !== '0') {
        missing.push(year);
        continue;
      }

      if (isTextType) {
        targetValues.push({ year, value: val });
      } else {
        const numVal = Number(val);
        if (isNaN(numVal)) {
          setTargetErrors(`Invalid number for year ${year}`);
          return;
        }
        if (numVal < 0) {
          setTargetErrors(`Year ${year}: value cannot be negative`);
          return;
        }
        targetValues.push({ year, value: numVal });
      }
    }

    if (missing.length > 0) {
      setTargetErrors(`Please fill target values for all years. Missing: ${missing.join(', ')}`);
      return;
    }

    // Validate sum equals overall target for numeric types
    if (!isTextType && !sumMatchesTarget) {
      setTargetErrors(`Sum of yearly targets (${yearlySum}) must exactly equal the overall target (${parsedOverallTarget}). Difference: ${remaining > 0 ? '+' : ''}${remaining}`);
      return;
    }

    await onSubmitTargets(parameter.id, targetValues, isTextType ? null : parsedOverallTarget);
  };

  // --- ACTUAL VALUES SECTION ---

  const handleActualInputChange = (cycle: number, field: keyof FormValues, value: string) => {
    setActualFormValues(prev => ({
      ...prev,
      [cycle]: {
        ...prev[cycle],
        [field]: field === 'textValue' ? value : (value ? Number(value) : undefined)
      }
    }));
    if (actualErrors[cycle]) {
      setActualErrors(prev => ({ ...prev, [cycle]: '' }));
    }
  };

  const validateActualForm = (cycle: number): boolean => {
    const values = actualFormValues[cycle];
    if (!values || (!values.actualValue && !values.textValue)) {
      setActualErrors(prev => ({ ...prev, [cycle]: 'Please enter a value' }));
      return false;
    }

    if (!isTextType) {
      const val = values.actualValue;
      if (val !== undefined && (val < 0 || val > parameter.maxValue)) {
        setActualErrors(prev => ({ ...prev, [cycle]: `Value must be between 0 and ${parameter.maxValue}` }));
        return false;
      }
    }

    return true;
  };

  const handleSubmitActual = async (cycle: number) => {
    if (validateActualForm(cycle)) {
      const success = await onSubmit(parameter.id, cycle, actualFormValues[cycle] || {});
      if (success) {
        setIsEditing(prev => ({ ...prev, [cycle]: false }));
      }
    }
  };

  const handleEditActual = (cycle: number) => {
    setIsEditing(prev => ({ ...prev, [cycle]: true }));
    const submitted = submittedValues[cycle];
    if (submitted) {
      setActualFormValues(prev => ({
        ...prev,
        [cycle]: {
          actualValue: submitted.actualValue,
          textValue: submitted.textValue,
        }
      }));
    }
  };

  const handleCancelEdit = (cycle: number) => {
    setIsEditing(prev => ({ ...prev, [cycle]: false }));
    setActualErrors(prev => ({ ...prev, [cycle]: '' }));
  };

  const getActualInputValue = (cycle: number, field: keyof FormValues): string => {
    const formVal = actualFormValues[cycle]?.[field];
    if (formVal !== undefined && formVal !== null) return formVal.toString();
    const submitted = submittedValues[cycle]?.[field];
    if (submitted !== undefined && submitted !== null) return submitted.toString();
    return '';
  };

  const isActualSubmitted = (cycle: number): boolean => {
    const sv = submittedValues[cycle];
    if (!sv) return false;
    if (isTextType) return !!(sv.textValue);
    return sv.actualValue !== undefined && sv.actualValue !== null;
  };

  const isActualFieldDisabled = (cycle: number): boolean => {
    if (isEditing[cycle]) return false;
    return isActualSubmitted(cycle);
  };

  const handleSubmitAllActuals = async () => {
    const toSubmit: { cycle: number; values: FormValues }[] = [];

    for (const cycleInfo of cycles) {
      if (!cycleInfo.enabled) continue;
      if (isActualFieldDisabled(cycleInfo.year)) continue;

      const values = actualFormValues[cycleInfo.year];
      if (values && (values.actualValue || values.textValue)) {
        if (!validateActualForm(cycleInfo.year)) return;
        toSubmit.push({ cycle: cycleInfo.year, values });
      }
    }

    if (toSubmit.length === 0) {
      return;
    }

    for (const { cycle, values } of toSubmit) {
      await onSubmit(parameter.id, cycle, values);
    }
  };

  // --- CUMULATIVE BACKLOG TRACKING ---

  // Compute cumulative stats for each activated year (only for numeric, locked targets)
  const cumulativeStats = useMemo(() => {
    if (isTextType || !targetValuesLocked) return {};

    const enabledYears = cycles.filter(c => c.enabled || isActualSubmitted(c.year)).map(c => c.year).sort((a, b) => a - b);
    const stats: { [year: number]: {
      yearTarget: number;
      yearActual: number | null;
      yearDiff: number | null;
      cumulTarget: number;
      cumulActual: number;
      cumulDiff: number | null;
      isSubmitted: boolean;
    }} = {};

    let cumulTarget = 0;
    let cumulActual = 0;

    for (const year of enabledYears) {
      const targetVal = Number(getTargetDisplayValue(year)) || 0;
      const sv = submittedValues[year];
      const hasActual = sv && sv.actualValue !== undefined && sv.actualValue !== null;
      const actualVal = hasActual ? Number(sv.actualValue) : null;

      cumulTarget += targetVal;
      if (hasActual) {
        cumulActual += actualVal!;
      }

      stats[year] = {
        yearTarget: targetVal,
        yearActual: actualVal,
        yearDiff: hasActual ? actualVal! - targetVal : null,
        cumulTarget,
        cumulActual: hasActual ? cumulActual : cumulActual,
        cumulDiff: hasActual ? cumulActual - cumulTarget : null,
        isSubmitted: !!hasActual,
      };
    }

    return stats;
  }, [cycles, submittedValues, targetValuesLocked, isTextType]);

  // Overall progress across all submitted actuals
  const overallProgress = useMemo(() => {
    if (isTextType || !targetValuesLocked || !savedOverallTarget) return null;

    const enabledYears = cycles.filter(c => c.enabled || isActualSubmitted(c.year)).map(c => c.year).sort((a, b) => a - b);
    let totalActual = 0;
    let totalTarget = 0;
    let submittedCount = 0;

    for (const year of enabledYears) {
      const targetVal = Number(getTargetDisplayValue(year)) || 0;
      totalTarget += targetVal;
      const sv = submittedValues[year];
      if (sv && sv.actualValue !== undefined && sv.actualValue !== null) {
        totalActual += Number(sv.actualValue);
        submittedCount++;
      }
    }

    if (submittedCount === 0) return null;

    const percentage = savedOverallTarget > 0 ? Math.round((totalActual / savedOverallTarget) * 100) : 0;

    return {
      totalActual,
      totalTarget,
      overallTarget: savedOverallTarget,
      diff: totalActual - totalTarget,
      percentage,
      submittedCount,
      totalYears: enabledYears.length,
    };
  }, [cycles, submittedValues, targetValuesLocked, savedOverallTarget, isTextType]);

  // --- RENDER ---

  return (
    <div className="expandable-parameter-form">
      {/* Parameter Header */}
      <div className="parameter-form-header">
        <h4>{parameter.name}</h4>
        <p className="form-description">{parameter.description}</p>
        <div className="form-meta">
          <span className="form-meta-tag">Type: {parameter.parameterType}</span>
          <span className="form-meta-tag">Max Value: {parameter.maxValue}</span>
        </div>
      </div>

      {/* SECTION A: Strategic Target Values */}
      <div className={`target-values-section ${targetValuesLocked ? 'locked' : 'unlocked'}`}>
        <div className="section-header">
          <div className="section-title-row">
            <Target size={18} className="section-icon" />
            <h5 className="section-title">Strategic Targets ({allCycleYears.length}-Year Plan)</h5>
          </div>
          {targetValuesLocked ? (
            <span className="status-badge status-locked">
              <Lock size={12} />
              Locked
            </span>
          ) : (
            <span className="status-badge status-pending">
              Pending
            </span>
          )}
        </div>

        {/* Overall Target Input (numeric only) */}
        {!isTextType && (
          <div className="overall-target-row">
            <div className="overall-target-label">
              <Target size={16} />
              <span>Overall Target ({allCycleYears[allCycleYears.length - 1]})</span>
            </div>
            {targetValuesLocked ? (
              <div className="overall-target-locked">
                {savedOverallTarget ?? '—'}
              </div>
            ) : (
              <div className="overall-target-input-wrapper">
                <input
                  type="number"
                  className="overall-target-input"
                  value={overallTargetInput}
                  onChange={(e) => handleOverallTargetChange(e.target.value)}
                  placeholder="Enter overall target"
                  min="0"
                  max={parameter.maxValue}
                  disabled={isSubmitting}
                />
                <span className="overall-target-hint">
                  Max: {parameter.maxValue}
                </span>
              </div>
            )}
          </div>
        )}

        {/* Yearly Target Inputs */}
        <div className="target-values-grid">
          {allCycleYears.map(year => {
            const displayVal = getTargetDisplayValue(year);
            const inputVal = getTargetInputValue(year);

            return (
              <div key={year} className="target-year-item">
                <label className="target-year-label">{year}</label>
                {targetValuesLocked ? (
                  <div className="target-value-locked">
                    {displayVal || '—'}
                  </div>
                ) : (
                  isTextType ? (
                    <textarea
                      className="target-input target-textarea"
                      value={inputVal}
                      onChange={(e) => handleTargetInputChange(year, e.target.value)}
                      placeholder={`Target for ${year}`}
                      rows={2}
                      disabled={isSubmitting}
                    />
                  ) : (
                    <input
                      type="number"
                      className="target-input"
                      value={inputVal}
                      onChange={(e) => handleTargetInputChange(year, e.target.value)}
                      placeholder="0"
                      min="0"
                      disabled={isSubmitting || !isOverallTargetValid}
                    />
                  )
                )}
              </div>
            );
          })}
        </div>

        {/* Live Allocation Tracker (numeric only, not locked) */}
        {!isTextType && !targetValuesLocked && isOverallTargetValid && (
          <div className={`allocation-tracker ${sumMatchesTarget ? 'match' : yearlySum > parsedOverallTarget ? 'over' : 'under'}`}>
            <div className="allocation-bar-container">
              <div
                className="allocation-bar-fill"
                style={{ width: `${Math.min((yearlySum / parsedOverallTarget) * 100, 100)}%` }}
              />
            </div>
            <div className="allocation-text">
              <span>Allocated: <strong>{yearlySum}</strong> / {parsedOverallTarget}</span>
              {sumMatchesTarget ? (
                <span className="allocation-status match">&#10003; Exact match</span>
              ) : yearlySum > parsedOverallTarget ? (
                <span className="allocation-status over">Exceeds by {yearlySum - parsedOverallTarget}</span>
              ) : (
                <span className="allocation-status under">Remaining: {remaining}</span>
              )}
            </div>
          </div>
        )}

        {targetErrors && (
          <div className="target-error-message">{targetErrors}</div>
        )}

        {!targetValuesLocked && (
          <div className="target-actions">
            <button
              type="button"
              className="btn btn-primary submit-targets-btn"
              onClick={handleSubmitAllTargets}
              disabled={isSubmitting || (!isTextType && !sumMatchesTarget)}
            >
              {isSubmitting ? (
                <>
                  <Loader2 className="animate-spin" size={14} />
                  Submitting...
                </>
              ) : (
                <>
                  <Lock size={14} />
                  Submit &amp; Lock All Targets
                </>
              )}
            </button>
            <p className="target-warning">
              Once submitted, target values cannot be changed.
            </p>
          </div>
        )}
      </div>

      {/* SECTION B: Actual Values */}
      <div className={`actual-values-section ${targetValuesLocked ? 'unlocked' : 'locked-overlay'}`}>
        <div className="section-header">
          <div className="section-title-row">
            <BarChart3 size={18} className="section-icon" />
            <h5 className="section-title">Actual Values</h5>
          </div>
        </div>

        {!targetValuesLocked ? (
          <div className="actual-locked-message">
            <Lock size={20} />
            <p>Submit target values for all years to unlock actual submissions.</p>
          </div>
        ) : (
          <div className="actual-values-container">
            {cycles.filter(c => c.enabled || isActualSubmitted(c.year)).map(cycleInfo => {
              const year = cycleInfo.year;
              const targetVal = getTargetDisplayValue(year);
              const submitted = isActualSubmitted(year);
              const disabled = isActualFieldDisabled(year);
              const stats = cumulativeStats[year];

              return (
                <div key={year} className={`actual-year-row ${submitted ? 'submitted' : ''}`}>
                  <div className="actual-year-info">
                    <span className="actual-year-label">{year}</span>
                    <span className="actual-target-ref">
                      Target: <strong>{targetVal || '—'}</strong>
                    </span>
                    
                  </div>

                  <div className="actual-input-area">
                    {isTextType ? (
                      <textarea
                        className={`actual-input actual-textarea ${submitted && !isEditing[year] ? 'read-only' : ''}`}
                        value={getActualInputValue(year, 'textValue')}
                        onChange={(e) => handleActualInputChange(year, 'textValue', e.target.value)}
                        disabled={disabled}
                        placeholder="Enter actual text value..."
                        rows={2}
                      />
                    ) : (
                      <div className="actual-numeric-input-wrapper">
                        <label className="actual-field-label">Actual Value:</label>
                        <input
                          type="number"
                          className={`actual-input ${submitted && !isEditing[year] ? 'read-only' : ''}`}
                          value={getActualInputValue(year, 'actualValue')}
                          onChange={(e) => handleActualInputChange(year, 'actualValue', e.target.value)}
                          disabled={disabled}
                          placeholder="Enter actual value"
                          min="0"
                          max={parameter.maxValue}
                        />
                      </div>
                    )}
                  </div>

                  {actualErrors[year] && (
                    <div className="actual-error">{actualErrors[year]}</div>
                  )}

                  <div className="actual-actions">
                    {cycleInfo.enabled && (!submitted || isEditing[year]) && (
                      <button
                        type="button"
                        className="btn btn-primary btn-sm"
                        onClick={() => handleSubmitActual(year)}
                        disabled={isSubmitting}
                      >
                        {isSubmitting ? <Loader2 className="animate-spin" size={14} /> : (isEditing[year] ? 'Update' : 'Submit')}
                      </button>
                    )}
                    {cycleInfo.enabled && submitted && !isEditing[year] && (
                      <button
                        type="button"
                        className="btn btn-secondary btn-sm"
                        onClick={() => handleEditActual(year)}
                        disabled={isSubmitting}
                      >
                        Edit
                      </button>
                    )}
                    {cycleInfo.enabled && isEditing[year] && (
                      <button
                        type="button"
                        className="btn btn-secondary btn-sm"
                        onClick={() => handleCancelEdit(year)}
                        disabled={isSubmitting}
                      >
                        Cancel
                      </button>
                    )}
                  </div>

                  {submitted && !isEditing[year] && submittedValues[year] && (
                    <div className="actual-submission-info">
                      Submitted: {new Date(submittedValues[year].submittedAt).toLocaleDateString()}
                    </div>
                  )}

                  {/* Backlog / Surplus indicator per year */}
                  {!isTextType && stats && stats.isSubmitted && !isEditing[year] && (
                    <div className="backlog-tracker">
                      <div className={`backlog-year-diff ${stats.yearDiff !== null && stats.yearDiff >= 0 ? 'surplus' : 'deficit'}`}>
                        {stats.yearDiff !== null && stats.yearDiff >= 0 ? (
                          <><TrendingUp size={13} /> Year: +{stats.yearDiff} above target</>
                        ) : (
                          <><TrendingDown size={13} /> Year: {stats.yearDiff} below target</>
                        )}
                      </div>
                      <div className={`backlog-cumulative ${stats.cumulDiff !== null && stats.cumulDiff >= 0 ? 'surplus' : 'deficit'}`}>
                        Cumulative: {stats.cumulActual} / {stats.cumulTarget}
                        {stats.cumulDiff !== null && (
                          <span className="backlog-cumul-badge">
                            {stats.cumulDiff >= 0 ? (
                              <><TrendingUp size={12} /> +{stats.cumulDiff} ahead</>
                            ) : (
                              <><AlertTriangle size={12} /> Backlog: {stats.cumulDiff}</>
                            )}
                          </span>
                        )}
                      </div>
                    </div>
                  )}
                </div>
              );
            })}

            {cycles.filter(c => c.enabled || isActualSubmitted(c.year)).length === 0 && (
              <div className="no-active-years-message">
                <p>No years are currently activated for actual submissions. Contact your administrator.</p>
              </div>
            )}

            {/* Overall Progress Summary */}
            {overallProgress && (
              <div className={`overall-progress-summary ${overallProgress.diff >= 0 ? 'on-track' : 'behind'}`}>
                <div className="progress-summary-header">
                  <BarChart3 size={16} />
                  <span className="progress-summary-title">Overall Progress</span>
                </div>
                <div className="progress-summary-bar-container">
                  <div
                    className="progress-summary-bar-fill"
                    style={{ width: `${Math.min(overallProgress.percentage, 100)}%` }}
                  />
                </div>
                <div className="progress-summary-details">
                  <div className="progress-summary-stat">
                    <span className="progress-stat-label">Actual (submitted)</span>
                    <span className="progress-stat-value">{overallProgress.totalActual}</span>
                  </div>
                  <div className="progress-summary-stat">
                    <span className="progress-stat-label">Target (submitted years)</span>
                    <span className="progress-stat-value">{overallProgress.totalTarget}</span>
                  </div>
                  <div className="progress-summary-stat">
                    <span className="progress-stat-label">Overall Target</span>
                    <span className="progress-stat-value">{overallProgress.overallTarget}</span>
                  </div>
                  <div className="progress-summary-stat">
                    <span className="progress-stat-label">Progress</span>
                    <span className="progress-stat-value">{overallProgress.percentage}%</span>
                  </div>
                  <div className={`progress-summary-stat highlight ${overallProgress.diff >= 0 ? 'surplus' : 'deficit'}`}>
                    <span className="progress-stat-label">{overallProgress.diff >= 0 ? 'Ahead' : 'Backlog'}</span>
                    <span className="progress-stat-value">
                      {overallProgress.diff >= 0 ? '+' : ''}{overallProgress.diff}
                    </span>
                  </div>
                </div>
                
              </div>
            )}
          </div>
        )}
      </div>

      {/* Footer Actions */}
      <div className="form-actions">
        {targetValuesLocked && cycles.filter(c => c.enabled).length > 0 && (
          <button
            type="button"
            className="btn btn-primary submit-all-btn"
            onClick={handleSubmitAllActuals}
            disabled={isSubmitting || Object.values(isEditing).some(e => e)}
          >
            {isSubmitting ? (
              <>
                <Loader2 className="animate-spin" size={16} />
                Submitting...
              </>
            ) : (
              'Submit All Actuals'
            )}
          </button>
        )}
        <button
          type="button"
          className="btn btn-secondary collapse-btn"
          onClick={onCollapse}
          disabled={isSubmitting}
        >
          <ChevronUp size={16} />
          Collapse
        </button>
      </div>
    </div>
  );
};

export default ExpandableParameterForm;
